import type { ServiceTranslation } from './App';

type Copy = [source: string, localized: string];
type VariantField = 'name' | 'description';
type CatalogCopy = Record<string, {
  fields: Partial<Record<keyof ServiceTranslation, Copy>>;
  variants: Record<string, Partial<Record<VariantField, Copy>>>;
}>;

// Exported Spanish catalog values guard against stale translations when a service is edited.
const italianCatalog: CatalogCopy = {
  "s1": {"fields":{"bookingName":["Diagnóstico Capilar con Microcámara","Analisi del cuoio capelluto con microcamera"],"name":["Lo que tu cabello esconde.","Quello che i tuoi capelli nascondono."],"slogan":["Tu cuero cabelludo tiene secretos. Vamos a verlos.","Il tuo cuoio capelluto ha dei segreti. Scopriamoli."],"description":["Conoce de cerca tu cuero cabelludo y cabello para entender qué cuidados necesitan.","Osserviamo da vicino il cuoio capelluto e i capelli per capire di quali cure hanno bisogno."],"includesText":["Realizamos un diagnóstico capilar con microcámara de aumento para observar el cuero cabelludo y el cabello. Valoramos el estado de los folículos visibles, la densidad capilar, el grosor del cabello y posibles alteraciones como exceso de grasa, descamación o sensibilidad.","Analisi con microcamera di ingrandimento. Valutiamo i follicoli visibili, la densità e lo spessore dei capelli e osserviamo eventuali segni di eccesso di sebo, desquamazione o sensibilità."],"achievedText":["Una valoración personalizada del estado de tu cuero cabelludo y cabello, con una explicación de lo que observamos y recomendaciones de cuidado adaptadas a tus necesidades.","Una valutazione personalizzata, con una spiegazione di ciò che osserviamo e consigli di cura adatti alle tue esigenze."],"forWhomText":["Si notas caída, menor densidad, caspa, grasa o molestias, o quieres mejorar tu rutina de cuidado.","Se noti caduta, minore densità, forfora, eccesso di sebo o fastidio, oppure vuoi migliorare la tua routine."],"conditionsText":["Los productos y tratamientos recomendados se cobran aparte. Análisis estético capilar; no sustituye una valoración dermatológica.","I prodotti e i trattamenti consigliati si pagano a parte. L’analisi ha finalità estetiche e non sostituisce una valutazione dermatologica."],"alertText":["⚠️ Solo diagnóstico capilar. No incluye peinado, ni tratamientos.","⚠️ Solo analisi dei capelli. Piega e trattamenti esclusi."]},"variants":{}},
  "1792246283319": {"fields":{"bookingName":["Test de Viabilidad & Resistencia","Test di fattibilità e resistenza"],"name":["¿Tu cabello está preparado para el cambio?","I tuoi capelli sono pronti al cambiamento?"],"slogan":["Antes de lanzarnos al color, hagamos la prueba.","Prima di passare al colore, facciamo una prova."],"description":["Antes de aclarar o transformar tu color, comprobamos cómo responde tu cabello.","Prima di schiarire o cambiare il colore, verifichiamo come reagiscono i tuoi capelli."],"includesText":["Realizamos una prueba sobre un pequeño mechón para valorar la resistencia, elasticidad y reacción del cabello ante el proceso químico previsto. Así comprobamos si es recomendable realizar la decoloración o el cambio de color deseado.","Eseguiamo un test su una piccola ciocca per valutarne resistenza, elasticità e reazione al processo chimico previsto. Verifichiamo così se la decolorazione o il cambio di colore desiderato è consigliabile."],"achievedText":["Una valoración profesional de cómo responde tu cabello y una recomendación sobre la viabilidad del cambio que deseas, priorizando siempre su resistencia y estado.","Una valutazione professionale della risposta dei capelli e un consiglio sulla fattibilità del cambiamento, nel rispetto della loro resistenza e del loro stato."],"forWhomText":["Si quieres pasar a un rubio más claro, realizar una decoloración o cambiar radicalmente de color, especialmente si llevas tintes, decoloraciones o tratamientos químicos anteriores.","Se vuoi un biondo più chiaro, una decolorazione o un cambio radicale, soprattutto se hai già effettuato colorazioni, decolorazioni o altri trattamenti chimici."],"conditionsText":["El importe se descuenta de tu posterior servicio de coloración o mechas reservado en L’Studio. La prueba orienta, pero no garantiza el resultado final.","Il costo viene detratto dal successivo servizio di colorazione o mèches prenotato da L’Studio. Il test è indicativo e non garantisce il risultato finale."],"alertText":["⚠️ Solo diagnóstico de viabilidad. No incluye coloración ni mechas.","⚠️ Solo test di fattibilità. Colorazione e mèches escluse."]},"variants":{}},
  "1792246333454": {"fields":{"bookingName":["Estudio Visagismo Capilar","Studio di visagismo per capelli"],"name":["¿Y si el problema no fuera tu cabello, sino el corte?","E se il problema fosse il taglio, anziché i tuoi capelli?"],"slogan":["Tu próximo look tiene estudio. Y hasta informe.","Il tuo prossimo look nasce da uno studio. Con un report dedicato."],"description":["Tu rostro tiene personalidad. Estudiamos tus facciones para encontrar el corte, volumen y color que mejor van contigo.","Studiamo i tuoi lineamenti per trovare il taglio, il volume e il colore che ti valorizzano di più."],"includesText":["Realizamos un estudio de visagismo mediante un programa digital especializado. Analizamos la forma del rostro, las facciones y las proporciones para asesorarte sobre los cortes, largos, flequillos, volúmenes y colores que mejor armonizan con tu imagen.","Usiamo un programma digitale specializzato per analizzare la forma del viso, i lineamenti e le proporzioni e consigliarti tagli, lunghezze, frange, volumi e colori in armonia con la tua immagine."],"achievedText":["Un informe personalizado con recomendaciones de estilo, corte y color, para que sepas qué opciones te favorecen y puedas decidir tu próximo cambio con confianza.","Un report personalizzato con consigli su stile, taglio e colore per scegliere il tuo prossimo cambiamento con sicurezza."],"forWhomText":["Si estás pensando en cambiar de look, dudas sobre qué corte o color elegir o quieres descubrir qué estilos encajan mejor con tus facciones y personalidad.","Se pensi di cambiare look, sei indecisa sul taglio o sul colore o vuoi capire quali stili valorizzano i tuoi lineamenti e la tua personalità."],"conditionsText":["Incluye estudio digital personalizado e informe de visagismo capilar y colorimetría. No incluye lavado, corte ni peinado. Los servicios de peluquería se reservan y cobran por separado, en otra cita.","Include lo studio digitale personalizzato e il report di visagismo e colorimetria. Lavaggio, taglio e piega sono esclusi. I servizi di parrucchiere si prenotano e pagano a parte, in un altro appuntamento."],"alertText":["⚠️ Solo es estudio de visagismo capilar & colorimetría, no incluye corte ni peinado.","⚠️ Include solo studio di visagismo e colorimetria. Taglio e piega esclusi."]},"variants":{}},
  "s4": {"fields":{"bookingName":["Color Raíces","Ritocco colore alla radice"],"name":["Tus raíces te están delatando.","La ricrescita ti sta tradendo."],"slogan":["Tu color de siempre. Como recién hecho.","Il tuo colore di sempre, come appena fatto."],"description":["Renueva tu color y devuelve la uniformidad a toda tu melena.","Rinnova il colore e ridona uniformità alla tua chioma."],"includesText":["Aplicación de coloración en el crecimiento de la raíz, hasta un máximo de 2 cm, para cubrir las canas o igualar el color existente. Incluye lavado profesional después de la coloración.","Applichiamo il colore sulla ricrescita fino a 2 cm per coprire i capelli bianchi o uniformare il colore esistente. Include il lavaggio professionale."],"achievedText":["Un color uniforme desde la raíz, con las canas cubiertas según el resultado acordado y sin necesidad de volver a colorear toda la melena.","Un colore uniforme alla radice con la copertura dei bianchi concordata, senza ricolorare tutta la chioma."],"forWhomText":["Si ya llevas el cabello teñido y quieres retocar el crecimiento, cubrir las canas o mantener tu tono habitual sin modificar el color de medios y puntas.","Se hai già i capelli tinti e vuoi ritoccare la ricrescita, coprire i bianchi o mantenere il tono abituale senza cambiare lunghezze e punte."],"conditionsText":["Solo raíces de hasta 2 cm; si el crecimiento es mayor, corresponde Color Integral. Incluye lavado, no peinado.","Solo per ricrescita fino a 2 cm. Per una ricrescita maggiore serve la colorazione completa. Include il lavaggio, non la piega."],"alertText":["⚠️ Para completar el servicio, selecciona el peinado según el largo de tu cabello.","⚠️ Per completare il servizio, seleziona la piega secondo la lunghezza dei capelli."]},"variants":{"v_m_1792609648240":{"name":["M","M"]},"v_l_1792609648240":{"name":["L","L"]},"v_xl_1792609648240":{"name":["XL","XL"]}}},
  "1792247910592": {"fields":{"bookingName":["Color Integral","Colorazione completa"],"name":["De la raíz a las puntas. Sin medias tintas.","Dalla radice alle punte. Senza mezze misure."],"slogan":["Un solo color. Toda una declaración.","Un solo colore, una vera dichiarazione di stile."],"description":["¿Tu color necesita algo más que un retoque? Es hora de darle protagonismo a toda tu melena. Coloración de raíz a puntas para renovar tu tono, recuperar la uniformidad y conseguir un acabado lleno de personalidad.","Se il tuo colore ha bisogno di più di un ritocco, rinnovalo dalla radice alle punte con un risultato uniforme e pieno di personalità."],"includesText":["Aplicación de coloración uniforme desde la raíz hasta las puntas para renovar, intensificar o cambiar el tono de toda la melena. Incluye asesoramiento sobre el color, aplicación y lavado profesional.","Colorazione uniforme dalle radici alle punte per rinnovare, intensificare o cambiare il tono. Include consulenza sul colore, applicazione e lavaggio professionale."],"achievedText":["Un color renovado y uniforme en toda la melena, con mayor intensidad, brillo y un acabado de tono más homogéneo desde la raíz hasta las puntas.","Un colore rinnovato e uniforme, più intenso e luminoso, dalla radice alle punte."],"forWhomText":["Si quieres teñir toda tu melena, recuperar un color apagado, igualar el tono de raíces y puntas o cambiar a un nuevo color sin realizar mechas ni decoloración.","Se vuoi colorare tutta la chioma, ravvivare un tono spento, uniformare radici e punte o cambiare colore senza mèches o decolorazione."],"conditionsText":["Incluye coloración integral y lavado. No incluye peinado, mechas, decoloración ni tratamientos adicionales. Precio según longitud y cantidad de cabello.","Include colorazione completa e lavaggio. Piega, mèches, decolorazione e trattamenti aggiuntivi sono esclusi. Prezzo in base a lunghezza e quantità di capelli."],"alertText":["⚠️ Para completar el servicio, selecciona el peinado según el largo de tu cabello.","⚠️ Per completare il servizio, seleziona la piega secondo la lunghezza dei capelli."]},"variants":{"v_m_1792247922296":{"name":["Color Corto","Colore · capelli corti"],"description":["Coloración completa cabello corto, estilo pixie","Colorazione completa per capelli corti, ad esempio taglio pixie."]},"v_l_1792247922296":{"name":["Color Medio","Colore · media lunghezza"],"description":["Coloración completa cabello hasta los hombros estilo Bob, media melena.","Colorazione completa per capelli fino alle spalle, come un bob o una media lunghezza."]},"v_xl_1792247922296":{"name":["Color Largo","Colore · capelli lunghi"],"description":["Coloración cpmpleta cabellos largos, desde hombros hasta media espalda.","Colorazione completa su capelli lunghi, dalle spalle fino a metà schiena."]},"v_1792248011383":{"name":["Color Extra-largo","Colore · capelli extra lunghi"],"description":["Coloración completa extra larga, cabellos desde media espalda hasta cintura.","Colorazione completa su capelli extra lunghi, da metà schiena fino alla vita."]}}},
  "1792248340199": {"fields":{"bookingName":["Matización & Tonalización","Tonalizzazione e correzione dei riflessi"],"name":["¿Tu rubio ya no es el que era?","Il tuo biondo non è più quello di prima?"],"slogan":["El tono correcto lo cambia todo.","Il tono giusto cambia tutto."],"description":["¿Tu rubio se ha puesto amarillo? ¿Tus reflejos se han vuelto anaranjados? ¿O simplemente tu color ha perdido ese matiz que tanto te gustaba? No necesitas empezar de cero. La matización & tonalización permiten corregir reflejos no deseados, ajustar la tonalidad y refrescar el color existente sin realizar un nuevo trabajo de mechas.","Il tuo biondo è diventato giallo? I riflessi sono aranciati o il colore ha perso la sfumatura che amavi? La tonalizzazione corregge i riflessi indesiderati e ravviva il colore senza rifare le mèches."],"includesText":["Aplicamos una tonalización personalizada para corregir o suavizar reflejos no deseados, como amarillos, anaranjados o cobrizos, y ajustar el matiz del cabello teñido o con mechas, sin realizar una nueva decoloración.","Applichiamo un tonalizzante su misura per correggere o attenuare riflessi gialli, aranciati o ramati nei capelli tinti o con mèches, senza una nuova decolorazione."],"achievedText":["Un color con los reflejos más equilibrados y el matiz renovado, recuperando el tono frío, neutro o cálido que buscas, según las posibilidades de tu base actual.","Riflessi più equilibrati e un tono freddo, neutro o caldo secondo le possibilità della tua base."],"forWhomText":["Si tus mechas han perdido el tono, tu rubio se ha vuelto amarillo o anaranjado, o quieres refrescar los reflejos de tu color sin volver a teñir o decolorar el cabello.","Se le mèches hanno perso il tono, il biondo è ingiallito o vuoi ravvivare i riflessi senza tingere o schiarire di nuovo."],"conditionsText":["No incluye mechas, decoloración ni peinado. El resultado depende de la base y del estado del cabello.","Mèches, decolorazione e piega escluse. Il risultato dipende dalla base e dallo stato dei capelli."],"alertText":["⚠️ Para completar el servicio, selecciona el peinado según el largo de tu cabello.","⚠️ Per completare il servizio, seleziona la piega secondo la lunghezza dei capelli."]},"variants":{"v_m_1792248344062":{"name":["Matiz Corto/Medio","Tonalizzazione · corti o medi"],"description":["Técnica en cabello corto para neutralizar los reflejos o subtonos indeseados que aparecen en el cabello, despues de una decoloración, tinte o por el paso del tiempo.","Tecnica su capelli corti per neutralizzare riflessi o sottotoni indesiderati dopo decolorazione, tinta o con il passare del tempo."]},"v_l_1792248344062":{"name":["Matiz Largo","Tonalizzazione · lunghi"],"description":["Técnica en cabello largo para neutralizar los reflejos o subtonos indeseados que aparecen en el cabello, despues de una decoloración, tinte o por el paso del tiempo.","Tecnica su capelli lunghi per neutralizzare riflessi o sottotoni indesiderati dopo decolorazione, tinta o con il passare del tempo."]},"v_xl_1792248344062":{"name":["Matiz Extra-largo","Tonalizzazione · extra lunghi"],"description":["Técnica en cabello Extra-largo para neutralizar los reflejos o subtonos indeseados que aparecen en el cabello, despues de una decoloración, tinte o por el paso del tiempo.","Tecnica su capelli extra lunghi per neutralizzare riflessi o sottotoni indesiderati dopo decolorazione, tinta o con il passare del tempo."]}}},
  "1792248673014": {"fields":{"bookingName":["Gloss Protein","Gloss Protein"],"name":["Tu pelo tiene derecho a brillar.","I tuoi capelli meritano di brillare."],"slogan":["Más brillo. Menos aspecto apagado.","Più brillantezza, meno opacità."],"description":["Hay días en los que tu pelo no necesita un cambio de color. Necesita recuperar su mejor versión. Gloss Protein es un servicio de brillo y cuidado capilar pensado para mejorar el aspecto de una melena apagada y devolverle luminosidad, suavidad y un acabado más pulido.","Quando non serve cambiare colore, Gloss Protein ravviva i capelli spenti con un trattamento di lucentezza e cura per un aspetto più morbido, luminoso e curato."],"includesText":["Incluye lavado profesional. El secado y peinado no están incluidos y se cobran por separado. Si deseas salir peinada, añade Styling & Peinados a tu reserva. No incluye nuevas mechas ni decoloración.","Include il lavaggio professionale. Asciugatura e piega si pagano a parte. Se vuoi uscire con la piega, aggiungi il servizio Styling e piega. Non include nuove mèches o decolorazione."],"achievedText":["Una melena de aspecto más cuidado, suave y brillante. De esas que apetece tocar.","Capelli dall’aspetto più curato, morbido e luminoso, da accarezzare."],"forWhomText":["Si notas el cabello apagado, sin brillo o con un aspecto poco cuidado y quieres darle un extra de luminosidad sin cambiar necesariamente tu color.","Se i tuoi capelli sono spenti o poco luminosi e vuoi ravvivarli senza necessariamente cambiare colore."]},"variants":{"v_m_1792248677261":{"name":["Gloss Corto/Medio","Gloss · corti o medi"],"description":["Refresca el tono y aporta brillo a tu cabello corto o media melena. Su proteína de trigo aporta cuerpo y vitalidad.","Ravviva il tono e aggiunge brillantezza ai capelli corti o medi. Le proteine del grano donano corpo e vitalità."]},"v_l_1792248677261":{"name":["Gloss largo","Gloss · lunghi"],"description":["Revitaliza el color y el brillo de tu melena larga, con proteína de trigo que ayuda a que el cabello se sienta más grueso y con cuerpo.","Ravviva il colore e la brillantezza dei capelli lunghi. Le proteine del grano aiutano a dare una sensazione di maggiore spessore e corpo."]},"v_xl_1792248677261":{"name":["Gloss Extra.largo","Gloss · extra lunghi"],"description":["Realza el tono y el brillo de tu melena extralarga. Su proteína de trigo aporta cuerpo y una apariencia más llena de vitalidad.","Valorizza il tono e la brillantezza dei capelli extra lunghi. Le proteine del grano donano corpo e un aspetto più vitale."]}}},
  "1792248852621": {"fields":{"bookingName":["Decoloración Raíces","Decolorazione della ricrescita"],"name":["¿Tu rubio empieza a tener raíces?","Il tuo biondo comincia a mostrare la ricrescita?"],"slogan":["Recuperamos la luz desde el principio.","Ritroviamo la luce fin dalle radici."],"description":["Tu rubio sigue siendo tu rubio. Pero las raíces tienen otros planes. La decoloración de raíces es un servicio técnico destinado a aclarar el crecimiento natural del cabello para mantener un rubio global o un color previamente decolorado, trabajando únicamente la zona de raíz.","La decolorazione della ricrescita schiarisce solo la radice naturale per mantenere la continuità di un biondo uniforme o di un colore già decolorato."],"includesText":["Aplicamos decoloración sobre el crecimiento natural de la raíz para aclararlo y mantener la continuidad de un cabello previamente decolorado. Adaptamos el proceso al estado del cabello y finalizamos con lavado profesional.","Applichiamo il decolorante alla ricrescita naturale. Adattiamo il processo allo stato dei capelli e concludiamo con un lavaggio professionale."],"achievedText":["Las raíces aclaradas para recuperar la continuidad de tu rubio o color decolorado, dejando el cabello preparado para aplicar el matiz necesario y conseguir el tono final deseado.","Radici schiarite in armonia con il biondo o con il colore decolorato, pronte per la tonalizzazione necessaria a ottenere il tono finale desiderato."],"forWhomText":["Si llevas una decoloración global o un rubio muy claro y necesitas aclarar el crecimiento de la raíz para mantener tu color. No es un servicio para cubrir canas ni para realizar mechas.","Se hai una decolorazione completa o un biondo molto chiaro e vuoi schiarire la ricrescita. Non è un servizio per coprire i capelli bianchi o fare mèches."],"conditionsText":["Incluye decoloración de raíces y lavado. Matiz, peinado y tratamientos se cobran aparte. Su realización depende del estado del cabello.","Include decolorazione della ricrescita e lavaggio. Tonalizzazione, piega e trattamenti si pagano a parte. La fattibilità dipende dallo stato dei capelli."],"alertText":["⚠️ Para completar el servicio, selecciona el peinado según el largo de tu cabello.","⚠️ Per completare il servizio, seleziona la piega secondo la lunghezza dei capelli."]},"variants":{}},
  "1792248908557": {"fields":{"bookingName":["Decoloración Integral","Decolorazione completa"],"name":["¿Quieres llevar tu color a otro nivel?","Vuoi portare il tuo colore a un altro livello?"],"slogan":["Los grandes cambios empiezan aclarando el camino.","I grandi cambiamenti iniziano facendo luce."],"description":["¿Sueñas con un cambio radical de color? Antes de elegir el tono, hay que preparar el lienzo. La decoloración integral es un servicio técnico de aclarado que trabaja toda la melena, desde la raíz hasta las puntas, para conseguir una base más clara sobre la que crear el color deseado.","La decolorazione completa schiarisce tutta la chioma, dalle radici alle punte, per creare una base più chiara su cui realizzare il colore desiderato."],"includesText":["Decoloración del cabello para aclarar su base y preparar la melena para un cambio importante de color. Valoramos previamente el estado del cabello y adaptamos la técnica y el proceso de aclarado a sus necesidades. Incluye lavado profesional.","Valutiamo prima lo stato dei capelli, adattiamo la tecnica e il processo e schiariamo la base per un cambio di colore importante. Include il lavaggio professionale."],"achievedText":["Una base de cabello aclarada, preparada para conseguir el tono final deseado mediante la coloración o tonalización correspondiente, siempre dentro de las posibilidades de tu cabello.","Una base più chiara, pronta per il colore o la tonalizzazione necessari al risultato desiderato, entro le possibilità dei tuoi capelli."],"forWhomText":["Si quieres pasar de un tono oscuro a uno mucho más claro, conseguir un rubio global o preparar tu cabello para un color que necesita una base previamente decolorada.","Se vuoi passare da un tono scuro a uno molto più chiaro, ottenere un biondo uniforme o preparare la base per un colore che richiede decolorazione."],"conditionsText":["Incluye decoloración y lavado. Matiz, peinado y tratamientos se cobran aparte. Su realización depende del estado y resistencia del cabello.","Include decolorazione e lavaggio. Tonalizzazione, piega e trattamenti si pagano a parte. Il servizio dipende dallo stato e dalla resistenza dei capelli."],"alertText":["⚠️ Para completar el servicio, selecciona el peinado según el largo de tu cabello.","⚠️ Per completare il servizio, seleziona la piega secondo la lunghezza dei capelli."]},"variants":{"v_m_1792248914460":{"name":["Decoloración Medio","Decolorazione · medi"]},"v_l_1792248914460":{"name":["Decoloración Largo","Decolorazione · lunghi"]},"v_xl_1792248914460":{"name":["Decoloración Extra-largo","Decolorazione · extra lunghi"]}}},
  "s5": {"fields":{"bookingName":["Mechas Tradicionales","Mèches tradizionali"],"name":["¿Tu cabello necesita un poco más de luz?","I tuoi capelli hanno bisogno di un po’ più di luce?"],"slogan":["Mechas que iluminan. Rubios que enamoran.","Mèches luminose, biondi che conquistano."],"description":["Hay clásicos que nunca pasan de moda. Y unas buenas mechas son uno de ellos. Las mechas tradicionales aportan luminosidad y contraste mediante la selección de mechones distribuidos por el cabello. Una técnica versátil para aclarar, iluminar y dar dimensión a tu melena.","Le mèches tradizionali schiariscono ciocche distribuite nella chioma per aggiungere luce, contrasto e profondità."],"includesText":["Realizamos mechas distribuidas por el cabello para aclarar determinadas zonas y aportar luminosidad, dimensión. Personalizamos el grosor, la cantidad y el tono de las mechas según el resultado deseado. Incluye matiz y lavado profesional y peinado.","Distribuiamo le mèches nei capelli e personalizziamo spessore, quantità e tonalità secondo il risultato desiderato. Include tonalizzazione, lavaggio e piega professionale."],"achievedText":["Una melena más luminosa, con reflejos personalizados que aportan profundidad, movimiento y un rubio adaptado a tu estilo. El matiz permite ajustar el tono final de las mechas.","Una chioma più luminosa, con riflessi su misura che aggiungono profondità e movimento. Il tonalizzante adatta il tono finale al tuo stile."],"forWhomText":["Si quieres iluminar tu cabello, conseguir reflejos rubios o aportar contraste y dimensión a tu color mediante mechas repartidas por la melena.","Se vuoi illuminare i capelli, ottenere riflessi biondi o aggiungere contrasto e dimensione con mèches distribuite nella chioma."],"conditionsText":["Servicio completo; Diagnostico y técnica de mechas, matiz adecuado al color, peinado profesional. Precio según longitud y modalidad SOFT (sutil) o FULL (Intenso)","Servizio completo con analisi, tecnica di mèches, tonalizzazione e piega professionale. Prezzo secondo lunghezza e formula SOFT, delicata, o FULL, intensa."],"alertText":["⚠️ En cabellos tratados químicamente, puede ser necesario realizar un test de viabilidad antes del servicio.","⚠️ Per capelli trattati chimicamente può servire un test di fattibilità prima del servizio."]},"variants":{"hf-22fbd786-d72b-4b9e-8483-d33b291a5802":{"name":["Medio · SOFT","Media lunghezza · SOFT"],"description":["Iluminación sutil en zonas seleccionadas.","Schiariture delicate nelle zone selezionate."]},"v2":{"name":["Medio · FULL","Media lunghezza · FULL"],"description":["Iluminación completa con mayor cantidad de mechas.","Schiaritura completa con una maggiore quantità di mèches."]},"hf-bb3bce09-8937-4d95-b313-edcb8e1f03df":{"name":["Largo · SOFT","Lunghi · SOFT"],"description":["Iluminación sutil en zonas seleccionadas.","Schiariture delicate nelle zone selezionate."]},"v3":{"name":["Largo · FULL","Lunghi · FULL"],"description":["Iluminación completa con mayor cantidad de mechas.","Schiaritura completa con una maggiore quantità di mèches."]},"hf-d5a144a3-b613-4b27-b4dd-93eea527e017":{"name":["Extralargo · SOFT","Extra lunghi · SOFT"],"description":["Iluminación sutil en zonas seleccionadas.","Schiariture delicate nelle zone selezionate."]},"v_1792249601978":{"name":["Extralargo · FULL","Extra lunghi · FULL"],"description":["Iluminación completa con mayor cantidad de mechas.","Schiaritura completa con una maggiore quantità di mèches."]}}},
  "1792249694609": {"fields":{"bookingName":["Mechas Parciales / Zonas Internas","Mèches parziali / zone interne"],"name":["¿Un toque de luz sin cambiarlo todo?","Un tocco di luce senza cambiare tutto?"],"slogan":["Pequeños reflejos. Grandes diferencias.","Piccoli riflessi, una grande differenza."],"description":["A veces, unas pinceladas de luz son suficientes para darle otro aire a tu melena. Las mechas parciales trabajan zonas seleccionadas del cabello para aportar luminosidad, realzar el movimiento y refrescar tu color sin necesidad de realizar un servicio de mechas completo.","Bastano a volte pochi tocchi di luce: le mèches parziali illuminano zone mirate e ravvivano il colore senza un servizio completo."],"includesText":["Realizamos mechas en zonas seleccionadas del cabello, como el contorno del rostro, la parte superior o áreas que necesitan recuperar luminosidad. Personalizamos su distribución y tonalidad. Incluye matiz y lavado profesional.","Realizziamo mèches in zone selezionate, come il contorno del viso o la parte superiore. Personalizziamo distribuzione e tonalità. Include tonalizzazione e lavaggio professionale."],"achievedText":["Más luz y dimensión en las zonas que más lo necesitan, con reflejos integrados en tu color actual y un resultado fresco sin transformar toda la melena.","Più luce e profondità nelle aree che ne hanno bisogno, con riflessi integrati nel tuo colore senza trasformare tutta la chioma."],"forWhomText":["Si quieres iluminar el rostro, refrescar tus mechas entre sesiones completas o añadir algunos reflejos sin aclarar todo el cabello.","Se vuoi illuminare il viso, ravvivare le mèches tra due sedute complete o aggiungere qualche riflesso senza schiarire tutti i capelli."],"conditionsText":["No incluye matiz, tratamientos capilares ni peinado, que deberán reservarse por separado, añadiendo los servicios. El precio puede variar según la longitud, densidad y cantidad de cabello trabajado. En cabellos previamente tratados químicamente, puede ser necesario realizar un Test de Viabilidad & Resistencia.","Tonalizzazione, trattamenti e piega vanno prenotati a parte. Il prezzo può variare con lunghezza, densità e quantità di capelli trattati. Per capelli già trattati chimicamente può servire un test di fattibilità e resistenza."],"alertText":["⚠️ Este servicio corresponde exclusivamente a la técnica de mechas parciales.","⚠️ Questo servizio comprende soltanto la tecnica delle mèches parziali."]},"variants":{}},
  "1792249762145": {"fields":{"bookingName":["Balayage Experience","Balayage Experience"],"name":["Mucho más que unas mechas. Una experiencia de color de principio a fin.","Molto più che mèches: un’esperienza di colore dall’inizio alla fine."],"slogan":["La luz donde más favorece. El color que evoluciona contigo.","Luce dove ti valorizza di più. Un colore che cresce con te."],"description":["¿Quieres iluminar tu cabello con un degradado natural y sin raíces marcadas? Creamos un balayage totalmente personalizado, con transiciones suaves y luminosidad donde más te favorece. Una experiencia completa que incluye diagnóstico previo, decoloración con protección, matiz o toner, esfumado de raíz si es necesario, tratamiento sellador y peinado profesional.","Creiamo un balayage personalizzato con transizioni morbide, luminosità mirata e senza ricrescita marcata. Include analisi, schiaritura protetta, tonalizzazione, sfumatura alla radice se necessaria, trattamento sigillante e piega."],"includesText":["Una experiencia completa de color que comienza con un diagnóstico capilar previo y el diseño de una técnica balayage personalizada. Realizamos la decoloración con protección, aplicamos el matiz para conseguir el tono deseado y, cuando es necesario, un esfumado de raíz para crear una transición natural. Finalizamos con un tratamiento sellador y peinado profesional.","Partiamo da un’analisi per progettare il balayage. Schiariamo con protezione, applichiamo il tonalizzante e sfumiamo la radice se serve. Concludiamo con trattamento sigillante e piega professionale."],"achievedText":["Un balayage diseñado para ti, con un degradado armonioso, un tono personalizado y una melena luminosa. Todo el proceso, desde la protección durante la decoloración hasta el peinado final, cuidado al detalle.","Un balayage su misura, con sfumature armoniose, un tono personalizzato e una chioma luminosa, dalla protezione durante la schiaritura alla piega."],"forWhomText":["Si buscas un cambio de color personalizado, con raíces integradas, luminosidad y un acabado natural. Ideal si quieres transformar tu melena con un servicio completo, sin tener que reservar por separado el matiz, el tratamiento y el peinado.","Se cerchi un colore su misura con radici integrate e un effetto naturale. La tonalizzazione, il trattamento e la piega fanno parte del servizio."],"conditionsText":["Sin un resultado favorable, no se realizará el balayage. El resultado final depende del estado del cabello. Precio según longitud y modalidad SOFT (sutil) o FULL (Intenso)","Il balayage si esegue solo se la valutazione è favorevole. Il risultato dipende dallo stato dei capelli. Prezzo secondo lunghezza e formula SOFT, delicata, o FULL, intensa."],"alertText":["⚠️En cabellos previamente tratados químicamente, será necesario realizar un Test de Viabilidad & Resistencia antes de confirmar el servicio.","⚠️ Per capelli già trattati chimicamente è necessario un test di fattibilità e resistenza prima di confermare il servizio."]},"variants":{"hf-b50d47cd-5333-48f9-b992-d769de80c62a":{"name":["Medio · SOFT","Media lunghezza · SOFT"],"description":["Iluminación sutil en zonas seleccionadas.","Schiariture delicate nelle zone selezionate."]},"v_m_1792249766265":{"name":["Medio · FULL","Media lunghezza · FULL"],"description":["Iluminación completa con mayor cantidad de mechas.","Schiaritura completa con una maggiore quantità di mèches."]},"hf-b65c765f-b950-471a-b3a7-2be33f145363":{"name":["Largo · SOFT","Lunghi · SOFT"],"description":["Iluminación sutil en zonas seleccionadas.","Schiariture delicate nelle zone selezionate."]},"v_l_1792249766265":{"name":["Largo · FULL","Lunghi · FULL"],"description":["Iluminación completa con mayor cantidad de mechas.","Schiaritura completa con una maggiore quantità di mèches."]},"hf-18882c72-e89c-45e4-91ec-1f52da9ab0bf":{"name":["Extralargo · SOFT","Extra lunghi · SOFT"],"description":["Iluminación sutil en zonas seleccionadas.","Schiariture delicate nelle zone selezionate."]},"v_xl_1792249766265":{"name":["Extralargo · FULL","Extra lunghi · FULL"],"description":["Iluminación completa con mayor cantidad de mechas.","Schiaritura completa con una maggiore quantità di mèches."]}}},
  "1792249914936": {"fields":{"bookingName":["Babylight Precission","Babylight Precission"],"name":["¿Un rubio lleno de luz, hasta el último detalle?","Un biondo luminoso fino all’ultimo dettaglio?"],"slogan":["Mechas delicadas. Luminosidad extraordinaria.","Mèches delicate, luminosità straordinaria."],"description":["¿Sueñas con un rubio luminoso, lleno de reflejos finos y naturales? Diseñamos unas babylights personalizadas con mechas ultrafinas que aportan luz y dimensión a tu melena.","Progettiamo babylights su misura, con mèches sottilissime per un biondo luminoso dai riflessi naturali."],"includesText":["Una experiencia completa de color que comienza con un diagnóstico capilar previo y el diseño personalizado de unas babylights: mechas ultrafinas que aportan luminosidad y dimensión al cabello. Realizamos la decoloración con protección, aplicamos el matiz para conseguir el tono deseado y, cuando es necesario, un esfumado de raíz para integrar los reflejos de forma natural. Finalizamos con un tratamiento sellador y peinado profesional.","Analisi preliminare e progetto di babylights personalizzato. Schiaritura con protezione, tonalizzazione e, se serve, sfumatura alla radice. Concludiamo con trattamento sigillante e piega professionale."],"achievedText":["Un rubio luminoso y multidimensional, con reflejos finos que se integran en tu melena. Un resultado personalizado, con el tono cuidado y el peinado final incluido.","Un biondo luminoso e sfaccettato, con riflessi fini ben integrati, tonalità personalizzata e piega finale inclusa."],"forWhomText":["Si quieres iluminar tu cabello con reflejos muy finos, conseguir un rubio elegante y natural o aportar más luz a tu melena sin un efecto de mechas gruesas o marcadas.","Se vuoi riflessi sottilissimi, un biondo naturale ed elegante o più luce senza mèches spesse o troppo marcate."],"conditionsText":["* En cabellos de alta densidad, porosidad elevada o con necesidades técnicas especiales, el presupuesto puede variar previa valoración. * El resultado dependerá del color de partida, el historial químico y la resistencia del cabello. Precio según longitud y modalidad SOFT (sutil) o FULL (Intenso)","Per capelli molto folti, porosi o con esigenze tecniche particolari il preventivo può variare dopo la valutazione. Il risultato dipende da colore di partenza, trattamenti precedenti e resistenza. Prezzo secondo lunghezza e formula SOFT o FULL."],"alertText":["⚠️ En cabellos previamente tratados químicamente, será necesario realizar un Test de Viabilidad & Resistencia antes de confirmar el servicio.","⚠️ Per capelli già trattati chimicamente è necessario un test di fattibilità e resistenza prima di confermare il servizio."]},"variants":{"hf-45624e32-b138-41b7-af0e-74d5bbb0a431":{"name":["Medio · SOFT","Media lunghezza · SOFT"],"description":["Iluminación sutil en zonas seleccionadas.","Schiariture delicate nelle zone selezionate."]},"v_m_1792249921856":{"name":["Medio · FULL","Media lunghezza · FULL"],"description":["Iluminación completa con mayor cantidad de mechas.","Schiaritura completa con una maggiore quantità di mèches."]},"hf-4d141b43-cd6b-449a-9fe3-3f8811d1f44c":{"name":["Largo · SOFT","Lunghi · SOFT"],"description":["Iluminación sutil en zonas seleccionadas.","Schiariture delicate nelle zone selezionate."]},"v_l_1792249921856":{"name":["Largo · FULL","Lunghi · FULL"],"description":["Iluminación completa con mayor cantidad de mechas.","Schiaritura completa con una maggiore quantità di mèches."]},"hf-fafa1bee-aa8a-4e69-a119-4b4ff86ddae0":{"name":["Extralargo · SOFT","Extra lunghi · SOFT"],"description":["Iluminación sutil en zonas seleccionadas.","Schiariture delicate nelle zone selezionate."]},"v_xl_1792249921856":{"name":["Extralargo · FULL","Extra lunghi · FULL"],"description":["Iluminación completa con mayor cantidad de mechas.","Schiaritura completa con una maggiore quantità di mèches."]}}},
  "1792250084664": {"fields":{"bookingName":["Hybrid Blond by L´Studio","Hybrid Blond by L’Studio"],"name":["Dos técnicas. Un resultado único. Totalmente tú.","Due tecniche, un risultato unico. Tutto tuo."],"slogan":["La precisión de las mechas. La naturalidad del balayage.","La precisione delle mèches, la naturalezza del balayage."],"description":["¿Quieres un rubio luminoso desde la raíz, pero con la suavidad de un degradado natural? Hybrid Experience combina la precisión de las mechas finas con la técnica balayage para crear un color personalizado, lleno de luz, profundidad y movimiento. Una experiencia completa diseñada para conseguir un rubio multidimensional, con reflejos integrados y una transición armoniosa entre raíces, medios y puntas.","Hybrid Experience combina mèches sottili e balayage per un biondo sfaccettato, luminoso già vicino alla radice, con una transizione morbida verso le punte."],"includesText":["Comenzamos con un diagnóstico previo para valorar el estado de tu cabello, tu color de partida y el resultado que deseas conseguir. Diseñamos una técnica híbrida personalizada que combina mechas finas Babylight y balayage, adaptando la distribución de la luminosidad a tu melena. Realizamos la decoloración con protección, aplicamos el matiz para conseguir el tono deseado y valoramos un esfumado de raíz cuando sea necesario. Finalizamos con un tratamiento sellador y peinado profesional.","Valutiamo lo stato dei capelli, il colore di partenza e il risultato desiderato. Progettiamo un mix di babylights e balayage, con schiaritura protetta, tonalizzazione ed eventuale sfumatura alla radice. Concludiamo con trattamento sigillante e piega professionale."],"achievedText":["Un rubio personalizado con luminosidad desde zonas próximas a la raíz y un degradado suave hacia las puntas. Un resultado con dimensión, movimiento y reflejos integrados, cuidado de principio a fin.","Un biondo su misura con luce vicino alle radici, sfumatura morbida verso le punte, movimento e riflessi integrati."],"forWhomText":["Si quieres combinar la luminosidad de unas babylights con la naturalidad de un balayage, conseguir un rubio más trabajado o iluminar tu melena sin perder profundidad en la raíz.","Se vuoi unire la luminosità delle babylights alla naturalezza del balayage, dando luce alle lunghezze senza perdere profondità alla radice."],"conditionsText":["* En cabellos de alta densidad, porosidad elevada o con necesidades técnicas especiales, el presupuesto puede variar previa valoración. Precio según longitud y modalidad SOFT (sutil) o FULL (Intenso)","Per capelli molto folti, porosi o con esigenze tecniche particolari il preventivo può variare dopo la valutazione. Prezzo secondo lunghezza e formula SOFT o FULL."],"alertText":["⚠️ En cabellos previamente tratados químicamente, será necesario realizar un Test de Viabilidad & Resistencia antes de confirmar el servicio.","⚠️ Per capelli già trattati chimicamente è necessario un test di fattibilità e resistenza prima di confermare il servizio."]},"variants":{"hf-42f3e751-1b33-40c7-a6ad-b557efb6087b":{"name":["Medio · SOFT","Media lunghezza · SOFT"],"description":["Iluminación sutil en zonas seleccionadas.","Schiariture delicate nelle zone selezionate."]},"v_m_1792250088687":{"name":["Medio · FULL","Media lunghezza · FULL"],"description":["Iluminación completa con mayor cantidad de mechas.","Schiaritura completa con una maggiore quantità di mèches."]},"hf-11b257ae-b0b6-4fcf-8eb8-614aeeade21a":{"name":["Largo · SOFT","Lunghi · SOFT"],"description":["Iluminación sutil en zonas seleccionadas.","Schiariture delicate nelle zone selezionate."]},"v_l_1792250088687":{"name":["Largo · FULL","Lunghi · FULL"],"description":["Iluminación completa con mayor cantidad de mechas.","Schiaritura completa con una maggiore quantità di mèches."]},"hf-8b29ef15-f747-44dd-8c46-b3da3f65d088":{"name":["Extralargo · SOFT","Extra lunghi · SOFT"],"description":["Iluminación sutil en zonas seleccionadas.","Schiariture delicate nelle zone selezionate."]},"v_xl_1792250088687":{"name":["Extralargo · FULL","Extra lunghi · FULL"],"description":["Iluminación completa con mayor cantidad de mechas.","Schiaritura completa con una maggiore quantità di mèches."]}}},
  "1794856922956": {"fields":{"name":["Contour Refresh","Contour Refresh"],"description":["Renueva la luz alrededor del rostro entre tus sesiones de Balayage, Babylights o Hybrid. Un retoque de contouring para refrescar tu melena y prolongar la armonía del color.","Ravviva la luce attorno al viso tra sedute di balayage, babylights o Hybrid. Un ritocco di contouring che mantiene l’armonia del colore."],"includesText":["Retoque de mechas en el contorno del rostro, adaptado a tu Balayage, Babylights o Hybrid.","Ritocco delle mèches lungo il contorno del viso, adattato al balayage, alle babylights o a Hybrid già realizzati."],"achievedText":["Un rostro más iluminado y una melena visualmente renovada, manteniendo la armonía de tu color.","Un viso più illuminato e una chioma dall’aspetto rinnovato, in armonia con il colore esistente."],"forWhomText":["Si llevas alguna de estas técnicas y quieres refrescar la luz alrededor del rostro entre tus sesiones completas, aproximadamente a los 4/5 mes.","Se vuoi ravvivare la luce attorno al viso tra due sedute complete, indicativamente dopo 4–5 mesi."],"conditionsText":["Servicio de mantenimiento localizado; no incluye renovar las mechas de toda la melena. Valoraremos previamente el estado de tu cabello para confirmar que es adecuado.","Manutenzione localizzata: non rinnova le mèches di tutta la chioma. Valutiamo prima lo stato dei capelli per verificarne l’idoneità."],"alertText":["⚠️ Servicio de mantenimiento exclusivo para mechas realizadas previamente en L’Studio.","⚠️ Trattamento di mantenimento riservato alle mèches già realizzate da L’Studio."]},"variants":{"v_m_1794857108842":{"name":["Contour Medio","Contour · medi"],"description":["Renueva la luz alrededor del rostro y refresca tu media melena entre sesiones de mechas.","Ravviva la luce attorno al viso e rinnova la media lunghezza tra due sedute di mèches."]},"v_l_1794857108842":{"name":["Contour Largo","Contour · lunghi"],"description":["Ilumina de nuevo el contorno del rostro, manteniendo la armonía de tu melena larga.","Ridona luce al contorno del viso, mantenendo l’armonia dei capelli lunghi."]},"v_xl_1794857108842":{"name":["Contour Extra-largo","Contour · extra lunghi"],"description":["Refresca la luz que enmarca tu rostro sin renovar las mechas de toda la melena.","Rinnova i riflessi che incorniciano il viso senza rifare le mèches su tutta la chioma."]}}},
  "s3": {"fields":{"bookingName":["Styling & Peinados","Styling e piega"],"name":["Hoy tienes cita con tu pelazo.","Oggi hai un appuntamento con capelli da favola."],"slogan":["Tú eliges el plan. Nosotras ponemos el estilo.","Tu scegli il programma. Noi pensiamo allo stile."],"description":["¿Liso impecable, ondas con movimiento o un acabado con personalidad? Tú eliges cómo quieres verte. Nosotras nos encargamos del pelazo.","Liscio impeccabile, onde morbide o una piega con carattere? Scegli il look e al resto pensiamo noi."],"includesText":["Lavado profesional, aplicación de productos de styling adaptados a tu cabello y peinado con secador y cepillo, plancha para conseguir el acabado que deseas: liso, con volumen o movimiento.","Lavaggio professionale, prodotti di styling adatti ai tuoi capelli e piega con phon, spazzola o piastra secondo l’effetto desiderato: liscio, volume o movimento."],"achievedText":["Un cabello limpio, con forma, movimiento y un acabado profesional. Ese efecto de recién salida del salón que en casa no siempre conseguimos.","Capelli puliti, con forma, movimento e un vero effetto da salone."],"forWhomText":["Si quieres llevar el cabello impecable sin tener que peinarte en casa, tienes una comida, una cita o simplemente te apetece regalarte un buen día de pelo.","Per un pranzo, un appuntamento o semplicemente per avere capelli in ordine senza doverli sistemare a casa."],"conditionsText":["Incluye lavado, productos de acabado y peinado profesional. No incluye corte, tratamientos ni coloraciones, si deseas añade en el catalogo los servicios restantes.","Include lavaggio, prodotti di finitura e piega professionale. Taglio, trattamenti e colore sono esclusi. Puoi aggiungerli dal catalogo."],"alertText":["⚠️ Selecciona el peinado según la longitud de tu cabello: Secado natural, Peinado corto, medio, largo o extralargo.","⚠️ Scegli secondo la lunghezza: asciugatura naturale o piega per capelli corti, medi, lunghi o extra lunghi."]},"variants":{"v_m_1792246653964":{"name":["Stylo Natural","Asciugatura naturale"],"description":["Lavado con productos profesionales y secado al aire sin pulido","Lavaggio con prodotti professionali e asciugatura all’aria, senza finitura."]},"v_l_1792246653964":{"name":["Stylo Corto","Piega · corti"],"description":["Lavado con productos profesionales peinado Cabello Corto","Lavaggio con prodotti professionali e piega su capelli corti."]},"v_xl_1792246653964":{"name":["Stylo Medio","Piega · medi"],"description":["Lavado con productos profesionales peinado Cabello Medio","Lavaggio con prodotti professionali e piega su capelli medi."]},"v_1792247320587":{"name":["Stylo Largo","Piega · lunghi"],"description":["Lavado con productos profesionales peinado Cabello Largo","Lavaggio con prodotti professionali e piega su capelli lunghi."]},"v_1793641193220":{"name":["Stylo Extra-Largo","Piega · extra lunghi"],"description":["Lavado con productos profesionales peinado Cabello Extra-Largo","Lavaggio con prodotti professionali e piega su capelli extra lunghi."]}}},
  "1792247137939": {"fields":{"bookingName":["Styling & Eventos","Styling per eventi"],"name":["El evento dura unas horas. Las fotos, para siempre.","L’evento dura poche ore. Le foto restano."],"slogan":["Tú disfruta del evento. Del pelazo nos encargamos nosotras.","Tu goditi l’evento. Ai capelli pensiamo noi."],"description":["Una boda, una fiesta o una noche especial. Tu melena merece estar a la altura, con un peinado trabajado y un acabado impecable.","Per un matrimonio, una festa o una serata speciale, regalati una piega curata e impeccabile."],"includesText":["Lavado y peinado profesional para ocasiones especiales. Trabajamos el cabello con técnicas de secado y herramientas de styling para crear ondas, volumen, movimiento o un acabado pulido, adaptado a tu look y al tipo de evento.","Lavaggio e piega professionale per occasioni speciali. Con phon e strumenti di styling creiamo onde, volume, movimento o un effetto liscio secondo il look e l’evento."],"achievedText":["Un peinado cuidado al detalle, con un acabado elegante y pensado para acompañarte durante tu celebración. Porque el vestido importa, pero el pelo también tiene que estar a la altura.","Una piega elegante, curata nei dettagli e pensata per accompagnarti durante i festeggiamenti."],"forWhomText":["Si tienes una boda, comunión, cena especial, fiesta o cualquier ocasión en la que quieras lucir un peinado más elaborado que el habitual, sin necesidad de llevar el cabello recogido.","Per matrimoni, comunioni, cene, feste e altre occasioni in cui vuoi una piega più elaborata ma con i capelli sciolti."],"conditionsText":["Desde 45 min. Incluye lavado y peinado de evento con cabello suelto. No incluye recogidos, semirrecogidos ni tratamientos. Precio según largo y elaboración.","Da 45 min. Include lavaggio e piega da evento con capelli sciolti. Raccolti, semiraccolti e trattamenti esclusi. Prezzo secondo lunghezza e lavorazione."],"alertText":["⚠️ Recuerda añadir tu peinado.","⚠️ Ricorda di aggiungere la piega."]},"variants":{"v_m_1792609102211":{"name":["Stylo Corto","Piega · corti"],"description":["Peinado Cabello Corto","Piega per capelli corti."]},"v_l_1792609102211":{"name":["Stylo Medio","Piega · medi"],"description":["Peinado Cabello Medio","Piega per capelli medi."]},"v_xl_1792609102211":{"name":["Stylo Largo","Piega · lunghi"],"description":["Peinado Cabello Largo","Piega per capelli lunghi."]}}},
  "1792246478702": {"fields":{"bookingName":["Corte Cambio Look - Tendencia","Taglio cambio look"],"name":["¿Lista para un corte que lo cambie todo?","Pronta per un taglio che cambia tutto?"],"slogan":["Nueva forma. Nuevo estilo. Misma esencia.","Nuova forma, nuovo stile. Sempre tu."],"description":["¿Llevas tiempo pensando en cambiar? Nos inspiramos en las tendencias para crear un corte diferente, actual y con tu personalidad.","Se pensi da tempo a un cambiamento, partiamo dalle tendenze per creare un taglio attuale che rispecchi la tua personalità."],"includesText":["Asesoramiento personalizado para elegir un nuevo corte según tu estilo, tipo de cabello y las tendencias actuales. Incluye lavado, corte de transformación y peinado profesional para lucir el resultado.","Consulenza personalizzata secondo stile, tipo di capelli e tendenze. Include lavaggio, taglio di trasformazione e piega professionale."],"achievedText":["Un cambio de look diseñado para renovar tu imagen, aportar movimiento y personalidad a tu cabello y hacerte sentir diferente sin dejar de ser tú.","Un cambio di look studiato per rinnovare la tua immagine e dare movimento e carattere alla chioma, senza perdere la tua essenza."],"forWhomText":["Si llevas tiempo con el mismo corte, quieres probar una tendencia o buscas un cambio de forma, longitud o estilo que vaya más allá de sanear las puntas.","Se hai lo stesso taglio da tempo o vuoi cambiare forma, lunghezza o stile, oltre a spuntare i capelli."],"conditionsText":["Duración aproximada: 60 min. Incluye lavado, corte y peinado profesional. No incluye estudio digital de visagismo, coloración ni tratamientos adicionales.","Circa 60 min. Include lavaggio, taglio e piega professionale. Esclusi studio digitale di visagismo, colore e trattamenti aggiuntivi."],"alertText":["⚠️ Para completar el servicio, selecciona el peinado según el largo de tu cabello.","⚠️ Per completare il servizio, seleziona la piega secondo la lunghezza dei capelli."]},"variants":{}},
  "1792246526630": {"fields":{"bookingName":["Corte Mantenimiento de puntas","Taglio di mantenimento delle punte"],"name":["¿Puntas abiertas? Hasta aquí hemos llegado.","Doppie punte? È ora di salutarle."],"slogan":["No queremos drama. Solo cortar lo justo.","Niente drammi. Tagliamo solo il necessario."],"description":["Te encanta tu melena y no quieres cambiarla. Perfecto. Saneamos las puntas y mantenemos su forma sin renunciar al largo que tanto te ha costado conseguir.","Ami la tua chioma così com’è? Sistemiamo le punte e manteniamo la forma senza sacrificare la lunghezza."],"includesText":["Lavado profesional, corte de mantenimiento para sanear las puntas y conservar la forma y longitud de tu melena, con peinado profesional para finalizar.","Lavaggio professionale, taglio di mantenimento per sistemare le punte e mantenere forma e lunghezza, seguito da piega professionale."],"achievedText":["Una melena con las puntas más cuidadas, un acabado más pulido y la tranquilidad de mantener tu estilo sin un cambio de look.","Punte più curate e una piega più ordinata, senza cambiare stile."],"forWhomText":["Si te gusta tu corte actual, pero notas las puntas secas, abiertas o desiguales y quieres mantener tu melena cuidada sin modificar su estilo.","Se ti piace il taglio attuale ma noti punte secche, aperte o irregolari e vuoi sistemarle."],"conditionsText":["Duración aproximada: 60 min. Incluye lavado, mantenimiento de puntas y peinado. No incluye cambios de estilo, coloración ni tratamientos adicionales.","Circa 60 min. Include lavaggio, spuntatura e piega. Cambio di stile, colore e trattamenti aggiuntivi esclusi."],"alertText":["⚠️ Para completar el servicio, selecciona el peinado según el largo de tu cabello.","⚠️ Per completare il servizio, seleziona la piega secondo la lunghezza dei capelli."]},"variants":{}},
  "1792246571414": {"fields":{"bookingName":["Corte Mujer - Cut&Go","Taglio donna · Cut&Go"],"name":["Un buen corte. Sin complicarte la agenda.","Un bel taglio, senza complicare l’agenda."],"slogan":["Menos tiempo en el salón. Más vida ahí fuera.","Meno tempo in salone, più tempo per te."],"description":["Para cuando necesitas poner tu corte al día sin dedicarle toda la mañana. Directo, práctico y sin complicaciones.","Per aggiornare il taglio senza passare tutta la mattina in salone. Un servizio diretto e pratico."],"includesText":["Lavado profesional y corte de cabello adaptado a tu estilo, con aplicación de producto de acabado. Un servicio práctico para renovar tu corte sin dedicar tiempo a un peinado elaborado.","Lavaggio professionale, taglio adatto al tuo stile e applicazione di un prodotto di finitura, senza una piega elaborata."],"achievedText":["Un corte renovado, cómodo y fácil de mantener, con un acabado sencillo para continuar con tu día sin perder tiempo.","Un taglio rinnovato, comodo e facile da mantenere, con un finish semplice."],"forWhomText":["Si necesitas renovar tu corte, tienes poco tiempo o prefieres un servicio sin peinado profesional con cepillo, plancha u ondas.","Se hai poco tempo o preferisci un taglio senza piega professionale con spazzola, piastra o onde."],"conditionsText":["Incluye lavado, corte y producto de acabado. No incluye peinado profesional, ni secado natural, ni tratamientos adicionales.","Include lavaggio, taglio e prodotto di finitura. Non include piega professionale, asciugatura naturale o trattamenti aggiuntivi."],"alertText":["⚠️ Servicio de lavado y corte. Acabado con producto profesional.","⚠️ Servizio di lavaggio e taglio, con prodotto professionale di finitura."]},"variants":{}},
  "1792246603493": {"fields":{"bookingName":["Corte Infantil - hasta 12 años","Taglio bambini · fino a 12 anni"],"name":["Pequeñas cabezas. Grandes estilos.","Piccole teste, grandi stili."],"slogan":["Porque tener estilo no tiene edad.","Lo stile non ha età."],"description":["Los pequeños también tienen mucho que decir sobre su pelo. Un corte cómodo, favorecedor y pensado para seguirles el ritmo.","Anche i più piccoli hanno le proprie idee sui capelli. Un taglio comodo che sta al loro ritmo."],"includesText":["Corte infantil personalizado para niños y niñas de hasta 12 años. Incluye lavado, corte adaptado al tipo de cabello y acabado natural, cómodo y fácil de mantener.","Taglio personalizzato per bambine e bambini fino a 12 anni, con lavaggio, taglio adatto al tipo di capelli e finish naturale facile da mantenere."],"achievedText":["Un corte bonito, práctico y adaptado a su edad, su cabello y su personalidad. Para que salgan del salón cómodos, arreglados y con mucho estilo.","Un taglio bello e pratico, adatto all’età, ai capelli e alla personalità."],"forWhomText":["Para niños y niñas de hasta 12 años que necesitan renovar su corte, sanear las puntas o estrenar un estilo nuevo adaptado a su día a día.","Per bambine e bambini fino a 12 anni che devono rinnovare il taglio, spuntare i capelli o provare uno stile nuovo."],"conditionsText":["Hasta 12 años · Desde 30 min. Incluye lavado, corte y acabado natural.","Fino a 12 anni, da 30 min. Include lavaggio, taglio e finish naturale."],"alertText":["⚠️","⚠️"]},"variants":{"v_m_1792608194029":{"name":["Corte Infantil Niño","Taglio bambino"],"description":["- Lavado, corte y acabado natural.","Lavaggio, taglio e finish naturale."]},"v_l_1792608194029":{"name":["Corte Infantil Niña","Taglio bambina"],"description":["- Lavado, corte y acabado natural.","Lavaggio, taglio e finish naturale."]},"v_1792608380277":{"name":["Corte Infantil Niña","Taglio bambina"],"description":["- Lavado, corte y secado con forma.","Lavaggio, taglio e asciugatura con messa in piega."]}}},
  "s8": {"fields":{"bookingName":["Corte Masculino","Taglio uomo"],"name":["Tu estilo. Tu personalidad. Nuestro toque.","Il tuo stile, la tua personalità, il nostro tocco."],"slogan":["Un buen corte no solo se ve. Se nota.","Un buon taglio si vede e si riconosce."],"description":["¿Buscas un corte que encaje contigo y con tu estilo de vida? En L’Studio Ana diseñamos cortes masculinos personalizados, teniendo en cuenta tus facciones, la textura de tu cabello y tus preferencias. Desde los estilos clásicos hasta las tendencias actuales, cuidamos cada detalle para conseguir un resultado natural, favorecedor y fácil de mantener.","Tagli uomo personalizzati secondo lineamenti, texture e preferenze. Dal classico alle tendenze, per un risultato naturale e facile da mantenere."],"includesText":["• Asesoramiento personalizado según tus facciones y estilo. • Corte masculino adaptado a las características de tu cabello. • Retoque de cejas para mantener una apariencia cuidada y natural. • Eliminación del vello visible de las orejas. • Revisión de contornos y detalles para un acabado impecable. **Porque la diferencia está en los pequeños detalles.**","Consulenza personalizzata, taglio adatto ai capelli, ritocco delle sopracciglia, rimozione dei peli visibili delle orecchie e revisione dei contorni."],"achievedText":["Un corte equilibrado, favorecedor y adaptado a las características de tu cabello, pensado para que puedas mantener tu estilo fácilmente en el día a día.","Un taglio equilibrato, valorizzante e adatto ai tuoi capelli, facile da gestire ogni giorno."],"forWhomText":["Si buscas renovar tu imagen, mantener tu corte habitual o encontrar un estilo que te favorezca y resulte cómodo de peinar.","Se vuoi rinnovare l’immagine, mantenere il taglio abituale o trovare uno stile che ti valorizzi e sia comodo da sistemare."],"conditionsText":["El corte se personaliza según el tipo de cabello, su longitud y el estilo deseado. Los cambios de imagen que requieran técnicas adicionales se valorarán previamente.","Il taglio si adatta al tipo e alla lunghezza dei capelli e allo stile desiderato. I cambiamenti che richiedono tecniche ulteriori vengono valutati prima."]},"variants":{}},
  "1792254773655": {"fields":{"bookingName":["Corte Masculino con arreglo Barba","Taglio uomo e regolazione barba"],"name":["Un estilo impecable, de principio a fin.","Uno stile impeccabile dall’inizio alla fine."],"slogan":["Tu estilo, cuidado hasta el último detalle.","Il tuo stile, curato nei minimi dettagli."],"description":["¿Buscas un look cuidado, equilibrado y con personalidad? Una experiencia de cuidado masculino que combina un corte de cabello personalizado con un arreglo de barba adaptado a tus facciones. Trabajamos la forma, los contornos y cada detalle para conseguir una imagen armoniosa, natural y elegante.","Un taglio personalizzato con una regolazione della barba su misura per i tuoi lineamenti, per un look naturale, elegante e armonioso."],"includesText":["• Asesoramiento personalizado de imagen. • Corte masculino adaptado a tu estilo y tipo de cabello. • Diseño y arreglo de barba según tus facciones. • Perfilado de contornos de barba, mejillas y cuello con shaver o navaja . • Retoque de cejas. • Eliminación del vello visible de las orejas. • Revisión de los detalles y acabado final.","Consulenza d’immagine, taglio, design e regolazione della barba. Profilatura di barba, guance e collo con rasoio elettrico o a lama. Ritocco sopracciglia, rimozione del pelo visibile dalle orecchie e finitura."],"achievedText":["Un corte favorecedor y una barba definida, con proporciones equilibradas y contornos cuidados. Una imagen renovada, elegante y fácil de mantener en tu día a día.","Un taglio valorizzante e una barba definita, con proporzioni armoniose e contorni in ordine, facili da mantenere."],"forWhomText":["Si buscas un servicio completo de cuidado masculino que combine cabello y barba, tanto para mantener tu estilo habitual como para renovar tu imagen.","Se vuoi un servizio completo per capelli e barba, per mantenere il tuo stile o rinnovarlo."],"conditionsText":["El corte y el arreglo de barba se personalizan según las características del cabello, la densidad de la barba y el estilo deseado. El servicio incluye arreglo y perfilado de barba con maquina Shaver o navaja. Los servicios de afeitado completo o rituales específicos no están incluidos.","Taglio e barba sono adattati a capelli, densità della barba e stile. Include rifinitura con rasoio elettrico o a lama. Rasatura completa e rituali specifici esclusi."],"alertText":["⚠️ Recuerda añadir tu peinado.","⚠️ Ricorda di aggiungere la piega."]},"variants":{"v_m_1792254777934":{"name":["Arreglo barba shaver","Barba · rasoio elettrico"]},"v_l_1792254777934":{"name":["Arreglo barba Navaja","Barba · rasoio a lama"]}}},
  "1792256948351": {"fields":{"bookingName":["Corte, Barba & Skin Care","Taglio, barba e cura del viso"],"name":["Tres cuidados. Una imagen impecable.","Tre cure, un look impeccabile."],"slogan":["Cabello, barba y piel. Todo habla de ti.","Capelli, barba e pelle: tutto parla di te."],"description":["¿Y si dedicaras un momento a cuidar tu imagen de principio a fin? Descubre nuestra experiencia de cuidado masculino más completa: corte personalizado, diseño de barba y un ritual facial Skin Care para cuidar tu piel. Un servicio pensado para renovar tu estilo, perfeccionar los detalles y disfrutar de una atención exclusiva.","Il nostro servizio uomo più completo: taglio su misura, design della barba e un rituale viso per la tua pelle."],"includesText":["• Asesoramiento personalizado de imagen. • Corte masculino adaptado a tus facciones y estilo. • Diseño, arreglo y perfilado de barba con máquina Shaver o navaja. • Retoque de cejas y eliminación del vello visible de las orejas. • Ritual facial Skin Care con limpieza y cuidado de la piel. • Revisión de contornos y detalles finales.","Consulenza, taglio, design e rifinitura della barba con rasoio elettrico o a lama. Ritocco sopracciglia, rimozione dei peli visibili delle orecchie, pulizia e cura del viso, controllo dei contorni e finitura."],"achievedText":["Un corte favorecedor, una barba perfectamente perfilada y una piel con una sensación de frescor y cuidado. Una imagen renovada y una experiencia de bienestar masculino que va más allá del corte habitual.","Taglio valorizzante, barba ben definita e pelle fresca e curata. Un momento di benessere che va oltre il taglio abituale."],"forWhomText":["Si buscas un cuidado masculino completo, quieres renovar tu imagen o disfrutar de un momento dedicado a ti. También es una experiencia ideal antes de una ocasión especial.","Se cerchi un trattamento uomo completo, vuoi rinnovare il look o dedicarti un momento prima di un’occasione speciale."],"conditionsText":["El corte, el arreglo de barba y el cuidado facial se adaptan a las necesidades de cada cliente. El servicio incluye perfilado de barba con máquina Shaver o navaja. No incluye afeitado completo ni tratamientos faciales especializados adicionales.","Taglio, barba e cura del viso sono personalizzati. Include rifinitura della barba con rasoio elettrico o a lama. Rasatura completa e trattamenti viso specialistici aggiuntivi esclusi."],"alertText":["⚠️ Recuerda añadir tu peinado.","⚠️ Ricorda di aggiungere la piega."]},"variants":{}},
  "s6": {"fields":{"bookingName":["Tratamento Intensivos","Trattamenti intensivi"],"name":["¿Tu cabello necesita algo más que una mascarilla?","Ai tuoi capelli serve più di una maschera?"],"slogan":["Un cuidado más profundo. Un cabello que vuelve a sentirse bien.","Una cura più profonda per capelli che tornano a stare bene."],"description":["¿Notas tu cabello seco, apagado, áspero o debilitado? En L’Studio Ana cuidamos tu melena con tratamientos intensivos personalizados, seleccionados según sus necesidades. Nuestro objetivo es mejorar su hidratación, nutrición, suavidad y aspecto, ayudándote a recuperar un cabello más manejable, brillante y cuidado. **Porque no todos los cabellos necesitan lo mismo. Y el tuyo merece un cuidado a medida.**","Se i capelli sono secchi, spenti, ruvidi o indeboliti, scegliamo un trattamento intensivo su misura per migliorare idratazione, nutrimento, morbidezza e aspetto."],"includesText":["Comenzamos valorando el estado de tu cabello para identificar sus necesidades y seleccionar el tratamiento intensivo más adecuado: hidratante, reparador, reconstructor o post-color. Incluye lavado con productos profesionales específicos y aplicación de un tratamiento personalizado para mejorar la hidratación, suavidad, resistencia cosmética o cuidado del color, según las necesidades de tu melena.","Valutazione dei capelli, lavaggio con prodotti professionali e applicazione del trattamento più adatto: idratante, riparatore, ricostruttivo o post-colore, secondo le esigenze della chioma."],"achievedText":["Un cabello más suave, manejable y cuidada, con una mejora de su aspecto, brillo y textura según sus necesidades. Además, conocerás qué cuidados puedes seguir en casa para ayudar a mantener los beneficios del tratamiento.","Capelli più morbidi e gestibili, con aspetto, lucentezza e texture migliorati secondo le esigenze. Ricevi indicazioni per continuare la cura a casa."],"forWhomText":["Si notas tu cabello seco, áspero, encrespado, apagado, frágil o sensibilizado por el uso de herramientas térmicas y procesos químicos. También si acabas de realizarte un servicio de color y quieres proporcionar a tu melena un cuidado específico.","Per capelli secchi, ruvidi, crespi, spenti, fragili o sensibilizzati da calore e trattamenti chimici. Anche dopo un servizio di colore."],"conditionsText":["El tratamiento se seleccionará según las necesidades y el estado del cabello. Los resultados pueden variar en función del daño previo y de los cuidados posteriores. Los tratamientos mejoran el aspecto y las propiedades cosméticas del cabello, pero no revierten de forma permanente los daños de la fibra capilar.","Il trattamento è scelto in base allo stato dei capelli. I risultati variano secondo il danno preesistente e le cure successive. Migliora l’aspetto e le proprietà cosmetiche, senza riparare in modo permanente i danni della fibra."],"alertText":["💧 Completa tu cuidado de hidratación y nutrición con nuestros bonos de tratamientos. Consulta «Bonos».","💧 Completa la cura idratante e nutriente con i nostri abbonamenti ai trattamenti. Consulta «Buoni e carte»."]},"variants":{}},
  "1792253741003": {"fields":{"bookingName":["Repair Balmain Hair Couture","Repair Balmain Hair Couture"],"name":["La alta costura también cuida tu cabello.","L’alta moda si prende cura anche dei tuoi capelli."],"slogan":["No es solo reparar tu cabello. Es cuidarlo con la elegancia de Balmain Paris.","Non solo riparazione: la cura con l’eleganza di Balmain Paris."],"description":["¿Tu cabello necesita una reparación a la altura de lo que merece? Descubre el lujo capilar de Balmain Hair Couture, la exclusiva firma parisina que traslada la sofisticación de la alta costura al cuidado del cabello. Un ritual intensivo de reparación y nutrición con fórmulas de alta gama, diseñado para devolver suavidad, flexibilidad y luminosidad a las melenas más exigentes.","Balmain Hair Couture porta la raffinatezza dell’alta moda parigina nei capelli. Un rituale intensivo di riparazione e nutrimento per ridare morbidezza, flessibilità e luminosità alla chioma."],"includesText":["Valoración del estado del cabello, lavado profesional y aplicación personalizada del tratamiento reparador Balmain Hair Couture. Un ritual de cuidado de lujo que combina fórmulas profesionales, atención al detalle y la exclusiva fragancia de la firma para ofrecer una experiencia capilar diferente.","Valutazione dei capelli, lavaggio professionale e applicazione personalizzata del trattamento riparatore Balmain Hair Couture, con formule professionali e la fragranza della maison."],"achievedText":["Una melena con mayor suavidad, brillo y manejabilidad, una sensación de nutrición intensa y el placer de haber disfrutado de un cuidado capilar de alta gama.","Capelli più morbidi, luminosi e facili da gestire, con una sensazione di nutrimento intenso e una cura di alta gamma."],"forWhomText":["Si tu cabello está seco, apagado, áspero o sensibilizado por coloraciones, decoloraciones y herramientas térmicas, y buscas un tratamiento reparador con el valor añadido de una firma de lujo.","Per capelli secchi, spenti, ruvidi o sensibilizzati da colori, decolorazioni o calore, quando cerchi un trattamento riparatore di lusso."],"conditionsText":["Incluye lavado y tratamiento Balmain Hair Couture. Los resultados dependen del estado inicial del cabello y de los cuidados posteriores. El peinado profesional se reserva aparte si no forma parte de la modalidad elegida.","Include lavaggio e trattamento Balmain Hair Couture. I risultati dipendono dallo stato iniziale e dalla cura successiva. La piega professionale si prenota a parte se non è inclusa nella formula scelta."],"alertText":["⚠️ Recuerda añadir tu peinado.","⚠️ Ricorda di aggiungere la piega."]},"variants":{}},
  "1792253800043": {"fields":{"bookingName":["Molecular Repair","Molecular Repair"],"name":["La nueva dimensión de la reparación capilar.","Una nuova dimensione per la riparazione dei capelli."],"slogan":["Porque un cabello bonito comienza con un cabello bien cuidado.","Capelli belli iniziano da capelli ben curati."],"description":["¿Sientes que tu cabello ha perdido fuerza, elasticidad y vitalidad? Descubre Molecular Repair Experience, una experiencia de cuidado capilar intensivo enfocada en mejorar la resistencia y el aspecto de la fibra capilar. Un tratamiento pensado para las melenas sensibilizadas que necesitan algo más que hidratación: un cuidado reparador avanzado para recuperar suavidad, movimiento y una apariencia saludable.","Un trattamento intensivo per migliorare la resistenza e l’aspetto della fibra, dedicato ai capelli sensibilizzati che hanno bisogno di più della sola idratazione."],"includesText":["• Valoración personalizada del estado del cabello. • Lavado profesional adaptado a sus necesidades. • Aplicación del protocolo Molecular Repair, siguiendo sus fases específicas de tratamiento. • Recomendaciones para prolongar los beneficios del cuidado en casa.","Valutazione personalizzata, lavaggio professionale adatto ai capelli, protocollo Molecular Repair con le sue fasi specifiche e consigli per prolungare i benefici a casa."],"achievedText":["Una melena con una sensación de mayor suavidad, flexibilidad y manejabilidad, y un aspecto más cuidado. Una experiencia reparadora especialmente diseñada para mimar el cabello que ha perdido vitalidad.","Capelli più morbidi, flessibili e facili da gestire, con un aspetto più curato."],"forWhomText":["Si tu cabello está debilitado, sensibilizado por decoloraciones o coloraciones, presenta rotura, se enreda con facilidad o ha perdido elasticidad y suavidad. Ideal si buscas un cuidado reparador más intensivo que un tratamiento de hidratación convencional.","Per capelli indeboliti o sensibilizzati da colore e decolorazione, soggetti a rottura, nodi o perdita di elasticità e morbidezza. Una cura più intensiva di una normale idratazione."],"conditionsText":["Los resultados pueden variar según el estado inicial del cabello y los cuidados posteriores. No sustituye el corte de las puntas dañadas cuando sea necesario.","I risultati variano in base allo stato iniziale e alle cure successive. Quando serve, il trattamento non sostituisce il taglio delle punte danneggiate."],"alertText":["⚠️Para completar el servicio, selecciona el peinado según el largo de tu cabello.","⚠️ Per completare il servizio, seleziona la piega secondo la lunghezza dei capelli."]},"variants":{}},
  "1792253865938": {"fields":{"bookingName":["Scalp Aromatherapy L´Studio","Scalp Aromatherapy L’Studio"],"name":["La ciencia del cuero cabelludo. El arte de cuidarte.","La scienza del cuoio capelluto. L’arte di prenderti cura di te."],"slogan":["Tu cuero cabelludo es único. Su tratamiento también.","Il tuo cuoio capelluto è unico. Anche il suo trattamento."],"description":["**¿Tu cuero cabelludo necesita un cuidado especializado?** Grasa, descamación, sensibilidad, sequedad o desequilibrios… Cada cuero cabelludo necesita una atención diferente. Descubre nuestros rituales **Scalp Therapy con Revivre Essence**, una línea profesional especializada en tricología capilar y cuidado de las alteraciones del cuero cabelludo. Trabajamos con **3 intensidades de tratamiento**, seleccionadas tras una valoración personalizada para adaptar el protocolo a tus necesidades. **Tu cuero cabelludo es único. Su tratamiento también.**","Per sebo, desquamazione, sensibilità, secchezza o altri squilibri, i rituali Scalp Therapy usano la linea professionale Revivre Essence. Scegliamo tra tre intensità dopo una valutazione personalizzata."],"includesText":["Valoración del cuero cabelludo, selección de la intensidad más adecuada, lavado profesional y aplicación del protocolo específico Revivre Essence. Cada ritual se personaliza según las necesidades detectadas.","Valutazione del cuoio capelluto, scelta dell’intensità, lavaggio professionale e applicazione del protocollo Revivre Essence secondo le esigenze rilevate."],"achievedText":["Un cuero cabelludo con una mayor sensación de limpieza, frescor y confort, acompañado de recomendaciones personalizadas para continuar su cuidado en casa.","Una maggiore sensazione di pulizia, freschezza e comfort, con consigli personalizzati per continuare la cura a casa."],"forWhomText":["Si notas exceso de grasa, descamación, sequedad, sensibilidad o molestias en el cuero cabelludo, o deseas incorporar un cuidado especializado a tu rutina capilar.","Se noti sebo in eccesso, desquamazione, secchezza, sensibilità o fastidio, o vuoi integrare un trattamento specifico nella tua routine."],"conditionsText":["La intensidad del ritual se determina mediante valoración profesional y no puede elegirse libremente. Según el estado del cuero cabelludo, pueden recomendarse varias sesiones o cuidados de mantenimiento. Los rituales son cosméticos y no sustituyen la atención dermatológica cuando sea necesaria. El tratamiento se abona al completo, y se van agendando las citas de semana en semana , según diagnóstico.","L’intensità è decisa dopo una valutazione professionale e non si sceglie liberamente. Possono servire più sedute o cure di mantenimento. Il rituale ha finalità cosmetiche e non sostituisce l’assistenza dermatologica. Si paga per intero e le sedute si fissano settimana per settimana secondo la valutazione."],"alertText":["⚠️ Para completar el servicio, selecciona el peinado según el largo de tu cabello.","⚠️ Per completare il servizio, seleziona la piega secondo la lunghezza dei capelli."]},"variants":{"v_m_1792253869658":{"name":["Therapy Basic","Therapy Basic"],"description":["Ritual de cuidado del cuero cabelludo con aceites esenciales y aromaterapia. Incluye una sesión al mes, personalizada según diagnóstico previo. El tratamiento se complementa con productos de mantenimiento para casa, recomendados según tus necesidades y adquiridos por separado.","Rituale con oli essenziali e aromaterapia per il cuoio capelluto. Include una seduta al mese, personalizzata dopo una valutazione. I prodotti di mantenimento per casa sono consigliati secondo le esigenze e acquistati a parte."]},"v_l_1792253869658":{"name":["Therapy plus","Therapy Plus"],"description":["Ritual intensivo de cuidado del cuero cabelludo con aceites esenciales y aromaterapia. Incluye una sesión semanal durante un mes, personalizada según diagnóstico previo. El tratamiento se complementa con productos de mantenimiento para casa, recomendados según tus necesidades y adquiridos por separado.","Rituale intensivo con oli essenziali e aromaterapia per il cuoio capelluto. Include una seduta alla settimana per un mese, personalizzata dopo una valutazione. I prodotti di mantenimento per casa sono consigliati secondo le esigenze e acquistati a parte."]},"v_xl_1792253869658":{"name":["Therapy Intensive","Therapy Intensive"],"description":["Ritual intensivo de cuidado del cuero cabelludo con aceites esenciales y aromaterapia. Incluye una sesión semanal durante dos meses o dos meses y medio, según diagnóstico previo. El tratamiento se complementa con productos de mantenimiento para casa, recomendados según tus necesidades y adquiridos por separado.","Rituale intensivo con oli essenziali e aromaterapia per il cuoio capelluto. Include una seduta alla settimana per due mesi o due mesi e mezzo, secondo la valutazione. I prodotti di mantenimento per casa sono consigliati secondo le esigenze e acquistati a parte."]}}},
  "1792254011058": {"fields":{"bookingName":["Head Spa Experience","Head Spa Experience"],"name":["Desconecta del mundo. Reconecta contigo.","Stacca dal mondo e torna a connetterti con te."],"slogan":["Tu cuero cabelludo es único. Su tratamiento también.","Il tuo cuoio capelluto è unico. Anche il suo trattamento."],"description":["¿Tu cuero cabelludo necesita un cuidado especializado? Grasa, descamación, sensibilidad, sequedad o desequilibrios… Cada cuero cabelludo necesita una atención diferente. Descubre nuestros rituales Scalp Therapy con Revivre Essence, una línea profesional especializada en tricología capilar y cuidado de las alteraciones del cuero cabelludo. Trabajamos con 3 intensidades de tratamiento, seleccionadas tras una valoración personalizada para adaptar el protocolo a tus necesidades.","I rituali Scalp Therapy con Revivre Essence offrono tre intensità scelte dopo una valutazione per sebo, desquamazione, sensibilità, secchezza o altri squilibri."],"includesText":["• Bienvenida con selección de tés para comenzar tu momento de relajación. • Valoración del cuero cabelludo y cabello según necesidades. • Lavado sensorial con productos profesionales. • Tratamiento capilar según necesidad. • Masaje craneal relajante. • Ritual de agua con aro Head Spa. • Tratamiento capilar personalizado. • Secado y acabado del cabello.","Selezione di tè di benvenuto, valutazione di capelli e cuoio capelluto, lavaggio sensoriale professionale, trattamento secondo le esigenze, massaggio rilassante alla testa, rituale d’acqua con arco Head Spa, trattamento personalizzato, asciugatura e finitura."],"achievedText":["Una sensación de relajación profunda, un cuero cabelludo fresco y confortable y una melena tratada con tratamientos profesional, suave y cuidada. Pero, sobre todo, un momento de calma para desconectar de la rutina y volver a conectar contigo.","Relax profondo, cuoio capelluto fresco e confortevole e capelli morbidi e curati, con un momento per staccare dalla routine."],"forWhomText":["Si necesitas desconectar del estrés diario, disfrutar de un masaje relajante y dedicarte un momento de bienestar. También es una experiencia ideal para regalar a alguien especial.","Per chi vuole prendersi una pausa dallo stress, godersi un massaggio rilassante o regalare l’esperienza a qualcuno."],"conditionsText":["Experiencia de bienestar y cuidado capilar con finalidad cosmética y relajante. El tratamiento se adapta a las necesidades del cabello y del cuero cabelludo. No sustituye los tratamientos dermatológicos cuando sean necesarios.","Esperienza cosmetica e rilassante, adattata alle esigenze dei capelli e del cuoio capelluto. Non sostituisce eventuali trattamenti dermatologici."],"alertText":["⚠️ Recuerda añadir tu peinado.","⚠️ Ricorda di aggiungere la piega."]},"variants":{"v_m_1792254015153":{"name":["Head Spa Pure","Head Spa Pure"],"description":["Tu pausa de bienestar. Una experiencia más breve para desconectar, disfrutar del cuidado capilar y recuperar la sensación de frescor y ligereza.","Una pausa di benessere più breve per staccare, prenderti cura dei capelli e ritrovare freschezza e leggerezza."]},"v_l_1792254015153":{"name":["Head Spa Zen","Head Spa Zen"],"description":["Desconecta de la cabeza a las manos. Una experiencia sensorial que combina el ritual Head Spa con un masaje de manos para disfrutar de un bienestar más completo.","Un’esperienza sensoriale che combina il rituale Head Spa con un massaggio alle mani per un benessere più completo."]},"v_xl_1792254015153":{"name":["Head Spa Prestige","Head Spa Prestige"],"description":["El lujo de dedicarte más tiempo. Nuestra experiencia más prolongada, con mayor duración del masaje craneal para disfrutar de una desconexión más profunda.","La nostra esperienza più lunga, con un massaggio alla testa prolungato per rilassarti più a fondo."]}}},
  "s7": {"fields":{"bookingName":["Terapia Orgánica Botox","Terapia organica Botox"],"name":["Una nueva vida para tu melena.","Una nuova vita per la tua chioma."],"slogan":["Devuélvele a tu melena el protagonismo que merece.","Ridona ai tuoi capelli il ruolo che meritano."],"description":["¿Tu cabello ha perdido suavidad, brillo y movimiento? Descubre nuestra Terapia Orgánica Botox, una experiencia de cuidado intensivo diseñada para revitalizar el aspecto de tu melena, mejorar su textura y ayudar a controlar el encrespamiento. Un ritual de belleza capilar para conseguir un cabello con una apariencia más sedosa, luminosa y manejable.","Un trattamento intensivo pensato per migliorare l’aspetto e la texture dei capelli, aiutare a controllare il crespo e renderli più morbidi, luminosi e facili da gestire."],"includesText":["Valoración personalizada del cabello, lavado preparador y aplicación del tratamiento Botox Capilar siguiendo el protocolo profesional, adaptado a las necesidades de tu melena.","Valutazione personalizzata, lavaggio preparatorio e applicazione del trattamento Botox per capelli secondo il protocollo professionale adatto alla tua chioma."],"achievedText":["Un cabello con mayor sensación de suavidad, brillo y manejabilidad, un aspecto más pulido y menos encrespamiento. Una melena que se siente más cuidada y resulta más fácil de peinar.","Capelli più morbidi, brillanti e facili da gestire, con un aspetto più ordinato e meno crespo."],"forWhomText":["Si notas tu cabello seco, poroso, apagado, áspero o con encrespamiento y buscas mejorar su aspecto sin recurrir necesariamente a un alisado.","Per capelli secchi, porosi, spenti, ruvidi o crespi, anche se non cerchi una lisciatura."],"conditionsText":["Precio personalizado según diagnóstico capilar. El importe del tratamiento se determina en función de tres factores: longitud, densidad y porosidad del cabello. Antes de realizar el servicio, valoraremos tu melena y te informaremos del precio correspondiente. Cada cabello es único y su tratamiento también.","Il costo viene definito dopo la valutazione, in base a lunghezza, densità e porosità. Ti comunichiamo il prezzo prima del servizio."],"alertText":["ℹ️ Servicio completo: incluye tratamiento y peinado profesional.","ℹ️ Servizio completo: include trattamento e piega professionale."]},"variants":{"v_m_1792254160920":{"name":["Terapia Botox Corto","Terapia Botox · corti"],"description":["Tratamiento intensivo que ayuda a reducir el frizz y aporta suavidad, brillo y manejabilidad al cabello. Cabello corto hasta oreja.","Trattamento intensivo per aiutare a ridurre il crespo e migliorare morbidezza, lucentezza e gestibilità. Capelli corti fino all’orecchio."]},"v_l_1792254160920":{"name":["Terapia Botox Medio","Terapia Botox · medi"],"description":["Tratamiento intensivo que ayuda a reducir el frizz y aporta suavidad, brillo y manejabilidad al cabello. Cabello medio hasta hombros.","Trattamento intensivo per aiutare a ridurre il crespo e migliorare morbidezza, lucentezza e gestibilità. Capelli medi fino alle spalle."]},"v_xl_1792254160920":{"name":["Terapia Botox Largo","Terapia Botox · lunghi"],"description":["Tratamiento intensivo que ayuda a reducir el frizz y aporta suavidad, brillo y manejabilidad al cabello. Cabello largo hasta media espalda.","Trattamento intensivo per aiutare a ridurre il crespo e migliorare morbidezza, lucentezza e gestibilità. Capelli lunghi fino a metà schiena."]}}},
  "1792254387849": {"fields":{"bookingName":["Terapia Orgánica Alisado","Terapia organica lisciante"],"name":["Menos encrespamiento. Más suavidad. Una melena más fácil de cuidar.","Meno crespo, più morbidezza. Una chioma più facile da curare."],"slogan":["Tu melena, más cómoda y fácil de cuidar.","Capelli più pratici, più facili da gestire."],"description":["¿Sueñas con un cabello más disciplinado, suave y fácil de peinar cada día? Descubre nuestra Terapia de Alisado Orgánico, un tratamiento profesional diseñado para reducir el encrespamiento, mejorar la manejabilidad y conseguir una melena con un acabado más pulido. Menos tiempo luchando con tu cabello. Más tiempo disfrutándolo.","Un trattamento professionale lisciante per ridurre il crespo, facilitare la gestione dei capelli e ottenere un risultato più ordinato."],"includesText":["Valoración personalizada del cabello, lavado preparador y aplicación del protocolo profesional de alisado orgánico, adaptado a las características de tu melena. Incluye los pasos técnicos necesarios para realizar el tratamiento y **secado al aire, sin peinado profesional**.","Valutazione personalizzata, lavaggio preparatorio e protocollo di lisciatura organica adattato ai tuoi capelli. Include le fasi tecniche e l’asciugatura all’aria, senza piega professionale."],"achievedText":["Un cabello más disciplinado, suave y manejable, con menos encrespamiento y mayor facilidad para arreglarlo en casa. El resultado dependerá de la estructura natural del cabello, su estado y el protocolo aplicado.","Capelli più disciplinati, morbidi e facili da sistemare a casa. Il risultato dipende dalla struttura naturale, dallo stato dei capelli e dal protocollo."],"forWhomText":["Si tienes el cabello encrespado, rebelde o difícil de manejar y buscas reducir el tiempo que dedicas a peinarlo. Ideal si deseas un acabado más controlado y una rutina capilar más sencilla.","Se i capelli sono crespi, ribelli o difficili da gestire e vuoi ridurre il tempo dedicato a sistemarli."],"conditionsText":["**El servicio no incluye peinado profesional.** Finaliza con secado al aire. Duración estimada hasta 6 meses, los resultados y su duración pueden variar según el estado inicial de la melena y los cuidados posteriores.","Non include la piega professionale. Si conclude con asciugatura all’aria. Durata prevista fino a 6 mesi; risultato e durata variano secondo lo stato iniziale e le cure successive."],"alertText":["⚠️ El precio final del alisado varía según los gramos de producto utilizados. Te informaremos del importe estimado antes y durante el servicio a realizar.","⚠️ Il prezzo finale della lisciatura varia secondo i grammi di prodotto utilizzati. Ti comunicheremo la stima prima e durante il servizio."]},"variants":{"v_m_1792254391775":{"name":["Alisado 50gr.","Lisciatura · 50 g"]},"v_l_1792254391775":{"name":["Alisado 80gr.","Lisciatura · 80 g"]},"v_xl_1792254391775":{"name":["Alisado 100gr.","Lisciatura · 100 g"]}}},
  "1792254568055": {"fields":{"bookingName":["Terapia Orgánica Nutrición Rizos","Terapia organica nutriente per ricci"],"name":["Rizos nutridos, definidos y llenos de vida.","Ricci nutriti, definiti e pieni di vita."],"slogan":["Porque tus rizos no necesitan cambiar. Necesitan el cuidado adecuado.","I tuoi ricci non devono cambiare: hanno bisogno della cura giusta."],"description":["¿Tus rizos han perdido definición, suavidad o elasticidad? Descubre nuestra Terapia Nutrición Rizos, un tratamiento intensivo diseñado para aportar nutrición y cuidado a los cabellos ondulados y rizados. Ayuda a controlar el encrespamiento, mejorar la suavidad y realzar la forma natural de tus rizos sin renunciar a su movimiento.","Un trattamento intensivo per capelli mossi e ricci, pensato per nutrire, ammorbidire, ridurre il crespo e valorizzare la forma naturale senza perdere movimento."],"includesText":["Valoración de las necesidades del cabello, lavado profesional y aplicación de un tratamiento nutritivo específico para cabellos ondulados y rizados. Un protocolo personalizado para mejorar la suavidad, flexibilidad y manejabilidad de tus rizos.","Valutazione delle esigenze, lavaggio professionale e applicazione di un trattamento nutriente specifico per capelli mossi e ricci. Il protocollo si adatta a morbidezza, elasticità e gestibilità desiderate."],"achievedText":["Rizos con mayor sensación de nutrición, suavidad y elasticidad, menos encrespamiento y una apariencia más cuidada. Una melena que conserva su movimiento natural.","Ricci più nutriti, morbidi ed elastici, con meno crespo e un aspetto più curato, conservando il movimento naturale."],"forWhomText":["Rizos con mayor sensación de nutrición, suavidad y elasticidad, menos encrespamiento y una apariencia más cuidada. Una melena que conserva su movimiento natural.","Per ricci che cercano più morbidezza, elasticità e cura senza rinunciare al movimento naturale."],"conditionsText":["Si tienes el cabello ondulado o rizado y notas sequedad, falta de definición, encrespamiento o dificultad para desenredarlo. Ideal para recuperar la suavidad y cuidar la belleza natural de tus rizos.","Adatto a capelli mossi o ricci, secchi, poco definiti, crespi o difficili da districare. Pensato per recuperare morbidezza e valorizzare il riccio naturale."],"alertText":["⚠️ Recuerda añadir tu peinado.","⚠️ Ricorda di aggiungere la piega."]},"variants":{}},
  "1792254609016": {"fields":{"bookingName":["Terapia Orgánica Cauterización","Terapia organica di cauterizzazione"],"name":["Un cuidado intensivo para devolverle belleza y suavidad a tu melena.","Una cura intensiva per ridare bellezza e morbidezza alla chioma."],"slogan":["Menos aspereza. Más suavidad. Un cabello que vuelve a brillar.","Meno ruvidità, più morbidezza. Capelli che tornano a brillare."],"description":["¿Notas tu cabello poroso, áspero, apagado o especialmente castigado? Descubre nuestra Terapia de Cauterización Capilar, un tratamiento intensivo diseñado para mejorar el aspecto de la fibra capilar, suavizar su textura y ayudar a controlar el encrespamiento. Un cuidado profesional para conseguir una melena más sedosa, luminosa y manejable.","Trattamento intensivo per capelli porosi, ruvidi, spenti o danneggiati. Migliora l’aspetto e la texture della fibra e aiuta a controllare il crespo."],"includesText":["Valoración personalizada del estado del cabello, lavado preparador y aplicación del tratamiento de cauterización capilar. Finalizamos con un **sellado térmico profesional mediante plancha**, ajustando la temperatura y la técnica a las características de tu cabello. Un ritual intensivo para mejorar la suavidad, el brillo y la apariencia de la fibra capilar.","Valutazione, lavaggio preparatorio e applicazione del trattamento di cauterizzazione. Concludiamo con una sigillatura termica professionale con piastra, adattando temperatura e tecnica ai capelli."],"achievedText":["Una melena con mayor sensación de suavidad, brillo y manejabilidad, una textura más uniforme y un aspecto más cuidado. Los resultados dependerán del estado inicial del cabello.","Una chioma più morbida, luminosa e facile da gestire, con texture più uniforme. Il risultato dipende dallo stato iniziale dei capelli."],"forWhomText":["Si tu cabello presenta porosidad, sequedad, encrespamiento, falta de brillo o una textura áspera, especialmente después de procesos químicos o del uso frecuente de herramientas térmicas.","Se i capelli sono porosi, secchi, crespi, spenti o ruvidi, soprattutto dopo trattamenti chimici o uso frequente di strumenti a caldo."],"conditionsText":["Incluye lavado, aplicación del tratamiento y sellado térmico con plancha. El protocolo se adapta al estado del cabello y los resultados pueden variar según su porosidad, sensibilidad y cuidados posteriores.","Include lavaggio, trattamento e sigillatura termica con piastra. Il protocollo si adatta allo stato dei capelli e il risultato può variare con porosità, sensibilità e cure successive."],"alertText":["⚠️ Recuerda añadir tu peinado.","⚠️ Ricorda di aggiungere la piega."]},"variants":{"v_m_1792254613070":{"name":["Cauterización Medio","Cauterizzazione · medi"]},"v_l_1792254613070":{"name":["Cauterización Largo","Cauterizzazione · lunghi"]},"v_xl_1792254613070":{"name":["Cauterización Extra-Largo","Cauterizzazione · extra lunghi"]}}},
  "1792254672655": {"fields":{"bookingName":["Terapia Detox Capilar","Terapia detox per capelli"],"name":["El cuidado que tu melena merece después del color.","La cura che i tuoi capelli meritano dopo il colore."],"slogan":["Porque un color bonito merece un acabado a su altura.","Un bel colore merita una finitura all’altezza."],"description":["¿Acabas de renovar tu color? Dale a tu cabello el cuidado que necesita. Nuestra Terapia Detox Capilar es un tratamiento post-color diseñado para ayudar a eliminar residuos del proceso de coloración y cuidar la fibra capilar después del servicio técnico. Un ritual que aporta suavidad, brillo y una sensación de cabello limpio, ligero y cuidado.","Trattamento post-colore pensato per aiutare a rimuovere i residui della colorazione e prendersi cura della fibra. Dona morbidezza, brillantezza e una sensazione di pulizia e leggerezza."],"includesText":["Valoración del estado del cabello tras el servicio de color, limpieza específica post-color y aplicación del protocolo Detox Capilar para ayudar a retirar residuos técnicos y acondicionar la fibra capilar.","Valutazione dei capelli dopo il colore, detersione specifica e protocollo Detox Capilar per aiutare a rimuovere i residui tecnici e condizionare la fibra."],"achievedText":["Una melena más suave, manejable y luminosa, con una sensación de limpieza y cuidado después del proceso de coloración.","Capelli più morbidi, luminosi e facili da gestire, con una sensazione di pulizia e cura dopo la colorazione."],"forWhomText":["Si acabas de realizarte una coloración o decoloración y quieres complementar el servicio con un cuidado específico para tu cabello.","Se hai appena fatto una colorazione o una decolorazione e vuoi abbinarla a una cura specifica per i capelli."],"conditionsText":["Tratamiento cosmético para la fibra capilar, especialmente indicado después de servicios de color. No es un tratamiento del cuero cabelludo. Sus resultados dependerán del estado del cabello y del protocolo aplicado.","Trattamento cosmetico della fibra indicato dopo il colore. Non è un trattamento per il cuoio capelluto. Il risultato dipende dallo stato dei capelli e dal protocollo applicato."],"alertText":["⚠️ Recuerda añadir tu peinado.","⚠️ Ricorda di aggiungere la piega."]},"variants":{}},
  "1795268374937": {"fields":{"bookingName":["Mantenimiento de raíces · Terapia de alisado","Ritocco della ricrescita · trattamento lisciante"],"name":["Tu cabello crece. Tu alisado se renueva desde la raíz.","I capelli crescono. La lisciatura si rinnova dalle radici."],"slogan":["Renueva tu alisado desde la raíz.","Rinnova la lisciatura a partire dalla ricrescita."],"description":["Retocamos el crecimiento para suavizar la diferencia entre la raíz nueva y los largos ya alisados. Antes de empezar, valoramos cómo ha crecido tu cabello y cómo se conserva el alisado anterior. Así podemos trabajar solo la zona que necesita el retoque.","Ritocchiamo la ricrescita per attenuare lo stacco tra le radici nuove e le lunghezze già lisciate. Prima valutiamo la crescita e come si è mantenuto il trattamento precedente."],"includesText":["Una valoración del crecimiento y del estado de tu alisado anterior. Aplicamos el tratamiento en la raíz nueva, trabajando por secciones para respetar los largos ya alisados.","Valutazione della ricrescita e della lisciatura precedente. Applichiamo il trattamento per sezioni solo alle radici nuove, rispettando le lunghezze già lisciate."],"achievedText":["Una transición más uniforme entre la raíz y los largos, con menos volumen en el crecimiento y un cabello más fácil de peinar en el día a día.","Uno stacco meno visibile tra radice e lunghezze, meno volume alla ricrescita e capelli più facili da sistemare ogni giorno."],"forWhomText":["Sí, si ya llevas un alisado y notas que la raíz ha recuperado su onda o volumen, mientras los largos siguen manteniendo el resultado. En la valoración veremos si un retoque de raíces es adecuado para tu cabello.","Se hai già una lisciatura e le radici sono tornate mosse o voluminose mentre le lunghezze sono ancora lisce. Valuteremo se il ritocco è adatto."],"conditionsText":["Este servicio está disponible únicamente si ya te has realizado un alisado. El retoque se aplica solo en las raíces que han crecido desde el tratamiento anterior.","Disponibile solo dopo una lisciatura precedente. Si trattano esclusivamente le radici cresciute dopo l’ultimo trattamento."],"alertText":["⚠️ Recuerda añadir tu peinado.","⚠️ Ricorda di aggiungere la piega."]},"variants":{}},
  "1792256684151": {"fields":{"bookingName":["Moldeado Parcial","Permanente parziale"],"name":["Un toque de movimiento, justo donde lo necesitas.","Un tocco di movimento, proprio dove serve."],"slogan":["Un pequeño cambio de textura. Una gran diferencia en tu estilo.","Un piccolo cambio di texture, una grande differenza nello stile."],"description":["¿Quieres aportar volumen, ondas o movimiento sin transformar toda tu melena? Nuestro Moldeado Parcial permite trabajar zonas específicas del cabello para conseguir una textura personalizada, respetando el resto de tu estilo. Ideal para dar forma, aportar cuerpo o crear ondas y rizos únicamente donde los deseas.","Aggiungi volume, onde o movimento solo nelle aree desiderate, rispettando il resto della chioma."],"includesText":["• Valoración de la estructura y resistencia del cabello. • Selección de las zonas que se van a moldear. • Preparación del cabello y aplicación del producto de moldeado. • Enrollado personalizado según el resultado deseado. • Neutralización y aclarado siguiendo el protocolo profesional. • Cuidado acondicionador posterior.","Valutazione della struttura e resistenza, scelta delle zone, preparazione, applicazione del prodotto, avvolgimento su misura, neutralizzazione, risciacquo e trattamento condizionante."],"achievedText":["Mayor volumen, movimiento u ondas en las zonas seleccionadas, con una textura adaptada a tu estilo y más posibilidades de peinado.","Più volume, movimento o onde nelle aree scelte, con una texture adatta al tuo stile e nuove possibilità di piega."],"forWhomText":["Si deseas aportar volumen en determinadas zonas, crear movimiento en medios o puntas o definir algunas áreas del cabello sin realizar un moldeado completo.","Se vuoi volume in alcune zone o movimento su lunghezze e punte senza una permanente completa."],"conditionsText":["El servicio se realiza únicamente en las zonas acordadas durante la valoración. En cabellos previamente tratados químicamente puede ser necesario realizar un Test de Viabilidad & Resistencia. El servicio estará sujeto a que el estado del cabello permita realizarlo con seguridad. La duración del resultado dependerá del tipo de cabello, la técnica aplicada y los cuidados posteriores.","Si lavora solo nelle zone concordate. Per capelli trattati chimicamente può servire un test di fattibilità e resistenza. Si procede solo se lo stato dei capelli lo permette in sicurezza. La durata dipende da capelli, tecnica e cure successive."],"alertText":["⚠️ Recuerda añadir tu peinado.","⚠️ Ricorda di aggiungere la piega."]},"variants":{}},
  "1792256718383": {"fields":{"bookingName":["Moldeador Completo","Permanente completa"],"name":["Transforma tu textura. Dale una nueva vida a tu melena.","Cambia la tua texture e dai nuova vita alla chioma."],"slogan":["Una nueva textura. Infinitas formas de ser tú.","Una nuova texture, infiniti modi di essere te."],"description":["Sueñas con una melena llena de rizos, volumen y movimiento? Nuestro Moldeado Completo transforma la textura de tu cabello para crear ondas o rizos duraderos, adaptados a tu estilo y personalidad. Personalizamos la técnica y el tamaño del rizo para conseguir un resultado favorecedor y con movimiento natural.","Una permanente su misura per onde o ricci duraturi. Adattiamo tecnica e dimensione del riccio per ottenere un risultato naturale e pieno di movimento."],"includesText":["• Valoración del estado, estructura y resistencia del cabello. • Lavado preparador. • Enrollado completo y personalizado según el rizo deseado. • Aplicación del producto de moldeado profesional. • Neutralización y aclarado. • Cuidado acondicionador posterior.","Valutazione di stato, struttura e resistenza, lavaggio preparatorio, avvolgimento completo su misura, applicazione del prodotto, neutralizzazione, risciacquo e trattamento condizionante."],"achievedText":["Una melena con ondas o rizos de mayor duración, volumen y movimiento, diseñada para adaptarse a tu estilo y facilitar nuevas posibilidades de peinado.","Onde o ricci più duraturi, volume e movimento, con nuove possibilità di piega adatte al tuo stile."],"forWhomText":["Si tienes el cabello liso o con poca definición y deseas transformar toda tu melena con ondas, rizos o una textura con más cuerpo y movimiento.","Per capelli lisci o poco definiti se vuoi trasformare tutta la chioma con onde, ricci o più corpo e movimento."],"conditionsText":["El servicio está sujeto a una valoración previa del estado y resistencia del cabello. En cabellos con tratamientos químicos anteriores puede ser obligatorio realizar un **Test de Viabilidad & Resistencia** antes del moldeado. El resultado dependerá de la estructura del cabello, su historial químico y los cuidados posteriores. **El precio puede variar según la longitud, densidad y cantidad de producto necesaria.**","Il servizio è soggetto a una valutazione preliminare. Dopo trattamenti chimici può essere obbligatorio un test di fattibilità e resistenza. Il risultato dipende da struttura, storia chimica e cure successive. Il prezzo può variare con lunghezza, densità e quantità di prodotto."],"alertText":["⚠️ Recuerda añadir tu peinado.","⚠️ Ricorda di aggiungere la piega."]},"variants":{"v_m_1792256721455":{"name":["Moldeador Corto","Permanente · corti"],"description":["Aporta forma, volumen y movimiento al cabello corto. Servicio completo con peinado profesional.","Dona forma, volume e movimento ai capelli corti. Servizio completo con piega professionale."]},"v_l_1792256721455":{"name":["Moldeador Medio","Permanente · medi"],"description":["Crea ondas y movimiento en tu media melena. Servicio completo con peinado profesional.","Crea onde e movimento sui capelli di media lunghezza. Servizio completo con piega professionale."]},"v_xl_1792256721455":{"name":["Moldeador Largo","Permanente · lunghi"],"description":["Define ondas y aporta movimiento al cabello largo. Servicio completo con peinado profesional.","Definisce le onde e dona movimento ai capelli lunghi. Servizio completo con piega professionale."]}}},
  "s9": {"fields":{"bookingName":["Diseño de Cejas","Design sopracciglia"],"name":["La expresión de tu mirada está en los detalles.","L’espressione del tuo sguardo sta nei dettagli."],"slogan":["Tus cejas. Tu expresión. Tu personalidad.","Le tue sopracciglia, la tua espressione, la tua personalità."],"description":["¿Sabías que unas cejas bien diseñadas pueden transformar la expresión de tu rostro? En L’Studio Ana personalizamos el diseño de tus cejas teniendo en cuenta tus facciones, su forma natural y el resultado que deseas conseguir. Buscamos el equilibrio perfecto para realzar tu mirada sin perder tu esencia.","Personalizziamo la forma delle sopracciglia secondo i tuoi lineamenti, la forma naturale e il risultato desiderato, per valorizzare lo sguardo senza perdere la tua essenza."],"includesText":["• Valoración de la forma natural de tus cejas. • Diseño personalizado según tus facciones. • Definición y limpieza del vello sobrante. • Perfilado y retoque de los detalles para conseguir un acabado armonioso.","Valutazione della forma naturale, disegno personalizzato, rimozione dei peli in eccesso e rifinitura per un risultato armonioso."],"achievedText":["Unas cejas más definidas, equilibradas y favorecedoras, que enmarcan tu mirada y realzan tu expresión de forma natural.","Sopracciglia più definite, equilibrate e valorizzanti, che incorniciano lo sguardo con naturalezza."],"forWhomText":["Si deseas mejorar la forma de tus cejas, corregir visualmente pequeñas asimetrías o simplemente mantenerlas cuidadas y definidas.","Se vuoi migliorare la forma, correggere visivamente piccole asimmetrie o tenerle curate e definite."],"conditionsText":["El diseño se adapta a la forma natural, densidad y crecimiento de las cejas. Utilizamos cera y pinzas según las características de la piel y el vello. En pieles sensibles o cuando existan contraindicaciones para la cera, se valorará la técnica más adecuada. No incluye tinte, laminado ni micropigmentación.","Il design segue forma, densità e crescita naturali. Usiamo cera o pinzette secondo pelle e peli. Per pelli sensibili o in caso di controindicazioni alla cera, valutiamo la tecnica più adatta. Tinta, laminazione e micropigmentazione escluse."]},"variants":{}},
  "1792256841487": {"fields":{"bookingName":["Depilación Labio Superior","Epilazione del labbro superiore"],"name":["Un pequeño detalle que marca la diferencia.","Un piccolo dettaglio che fa la differenza."],"slogan":["Una piel cuidada también está en los pequeños detalles.","La cura della pelle si vede anche nei dettagli."],"description":["Eliminamos delicadamente el vello del labio superior para conseguir un acabado limpio, suave y natural. Un servicio rápido y preciso para sentirte cómoda y cuidar tu imagen.","Rimuoviamo delicatamente i peli del labbro superiore per un finish pulito, morbido e naturale. Un servizio rapido e preciso."],"includesText":["• Valoración de la zona y sensibilidad de la piel. • Depilación del labio superior con cera. • Retoque con pinzas si es necesario. • Cuidado calmante al finalizar.","Valutazione della zona e della sensibilità, epilazione con cera, eventuale ritocco con pinzette e cura lenitiva finale."],"achievedText":["Una zona del labio superior libre de vello visible, con un acabado limpio y cuidado.","Labbro superiore senza peli visibili, con un risultato pulito e curato."],"forWhomText":["Si deseas eliminar el vello del labio superior de forma rápida y mantener una apariencia natural y cuidada.","Se vuoi eliminare rapidamente i peli del labbro superiore per un aspetto naturale e curato."],"conditionsText":["La depilación se realizará siempre que el estado de la piel lo permita. Se evitará la cera en piel irritada, lesionada o sensibilizada por determinados tratamientos cosméticos o dermatológicos. Puede aparecer un ligero enrojecimiento temporal después del servicio.","L’epilazione si esegue solo se lo stato della pelle lo consente. Si evita la cera su pelle irritata, lesionata o sensibilizzata da trattamenti cosmetici o dermatologici. Può comparire un lieve arrossamento temporaneo."],"alertText":["⚠️ Recuerda añadir tu peinado.","⚠️ Ricorda di aggiungere la piega."]},"variants":{}},
  "1792256871175": {"fields":{"bookingName":["Diseño cejas & Labio Superior","Design sopracciglia ed epilazione del labbro superiore"],"name":["Dos cuidados esenciales para una expresión impecable.","Due cure essenziali per un’espressione impeccabile."],"slogan":["Una mirada definida y una piel cuidada en una sola cita.","Sguardo definito e pelle curata in un solo appuntamento."],"description":["¿Quieres realzar tu mirada y cuidar cada detalle de tu rostro? Combinamos el diseño personalizado de cejas con la depilación del labio superior para conseguir un acabado natural, limpio y armonioso.","Abbiniamo il design personalizzato delle sopracciglia all’epilazione del labbro superiore per un risultato naturale e armonioso."],"includesText":["• Valoración y diseño de cejas según tus facciones. • Depilación de cejas con cera y pinzas. • Perfilado y definición de la forma. • Depilación del vello del labio superior con cera. • Retoques de precisión con pinzas cuando sea necesario. • Cuidado calmante al finalizar.","Valutazione e disegno secondo i lineamenti, epilazione delle sopracciglia con cera e pinzette, definizione del contorno, epilazione del labbro superiore con cera, eventuali ritocchi con pinzette e cura lenitiva finale."],"achievedText":["Unas cejas definidas que realzan tu mirada y un labio superior libre de vello visible. Un resultado natural, equilibrado y cuidado.","Sopracciglia definite e labbro superiore senza peli visibili, con un risultato naturale, equilibrato e curato."],"forWhomText":["Si deseas mantener tus cejas perfectamente diseñadas y eliminar el vello del labio superior en una misma sesión.","Se vuoi definire le sopracciglia e rimuovere i peli del labbro superiore in un’unica seduta."],"conditionsText":["El diseño se adapta a la forma natural y densidad de tus cejas. La depilación se realizará siempre que el estado de la piel lo permita. En pieles irritadas, sensibilizadas o con tratamientos dermatológicos incompatibles con la cera, se valorará la técnica adecuada. No incluye tinte ni laminado de cejas.","Il design segue forma e densità naturali. L’epilazione si esegue solo se la pelle lo permette. Per pelli irritate, sensibilizzate o con trattamenti incompatibili con la cera si valuta la tecnica adatta. Tinta e laminazione escluse."],"alertText":["⚠️ Recuerda añadir tu peinado.","⚠️ Ricorda di aggiungere la piega."]},"variants":{}},
  "1792256900911": {"fields":{"bookingName":["Coloración Cejas","Tinta sopracciglia"],"name":["Más definición, más expresión. Tu mirada, naturalmente tú.","Più definizione, più espressione. Il tuo sguardo naturale."],"slogan":["Pequeños detalles que transforman tu mirada.","Piccoli dettagli che trasformano il tuo sguardo."],"description":["¿Tus cejas son demasiado claras o han perdido intensidad? Realza tu mirada con nuestra Coloración de Cejas, un servicio personalizado que aporta intensidad, uniformidad y definición al color natural de tus cejas. Seleccionamos el tono más favorecedor según tus facciones, cabello y estilo, buscando un resultado elegante y armonioso.","Se le sopracciglia sono troppo chiare o hanno perso intensità, una tinta personalizzata dona colore più uniforme e definizione. Scegliamo il tono in base a lineamenti, capelli e stile."],"includesText":["• Valoración del tono natural de tus cejas y cabello. • Selección personalizada del color. • Aplicación de coloración específica para cejas. • Retirada del producto y revisión del resultado final.","Valutazione del tono naturale di sopracciglia e capelli, scelta personalizzata, applicazione di una tinta specifica, rimozione e verifica del risultato."],"achievedText":["Unas cejas con un color más uniforme, mayor definición visual y una mirada más expresiva, manteniendo un acabado natural.","Sopracciglia dal colore più uniforme e più definite, con uno sguardo espressivo e un risultato naturale."],"forWhomText":["Si tienes las cejas claras, con pequeñas diferencias de tonalidad o deseas intensificar su color sin necesidad de maquillarlas a diario.","Se hai sopracciglia chiare, lievi differenze di tono o vuoi intensificarle senza truccarle ogni giorno."],"conditionsText":["El resultado y la duración dependen del tipo de vello, el tono elegido y los cuidados posteriores. Se utilizarán productos específicos para cejas y se comprobarán las posibles sensibilidades o contraindicaciones antes de la aplicación. No incluye diseño, depilación, laminado ni micropigmentación.","Risultato e durata dipendono dal tipo di pelo, dal tono e dalla cura successiva. Prima dell’applicazione si verificano sensibilità o controindicazioni e si usano prodotti specifici. Sono esclusi design, epilazione, laminazione e micropigmentazione."],"alertText":["⚠️ Recuerda añadir tu peinado.","⚠️ Ricorda di aggiungere la piega."]},"variants":{}}
};

function resolveCopy(copy: Copy | undefined, original: string | undefined): string {
  return copy && original?.trim().replace(/\s+/g, ' ') === copy[0] ? copy[1] : '';
}

export function catalogServiceCopy(language: string, id: string, field: keyof ServiceTranslation, original: string | undefined): string {
  return language === 'it' ? resolveCopy(italianCatalog[id]?.fields[field], original) : '';
}

export function catalogVariantCopy(language: string, serviceId: string, variantId: string, field: VariantField, original: string | undefined): string {
  return language === 'it' ? resolveCopy(italianCatalog[serviceId]?.variants[variantId]?.[field], original) : '';
}

const serviceCardLabels = {
  imageIllustrative: ['Imagen ilustrativa', 'Immagine illustrativa'],
  imageEnlarge: ['Ampliar imagen', 'Ingrandisci l’immagine'],
  suitableFor: ['¿Es para ti?', 'Fa per te?'],
  assessment: ['Valoración previa', 'Valutazione preliminare'],
  approval: ['Reserva bajo confirmación de Ana', 'Prenotazione soggetta alla conferma di Ana'],
  toner: ['Matiz', 'Tonalizzazione'],
  styling: ['Peinado', 'Piega'],
  notice: ['Aviso', 'Avviso'],
  addStyling: ['Recuerda añadir tu peinado para asegurar el tiempo en agenda.', 'Ricorda di aggiungere la piega per riservare il tempo necessario.'],
} as const;

export function serviceCardLabel(language: string, key: keyof typeof serviceCardLabels): string {
  return serviceCardLabels[key][language === 'it' ? 1 : 0];
}
